    local function Corner(Parent, Radius)
        local Value = tonumber(Radius) or 0
        if Value >= 90 then
            Value = 999
        else
            Value = 0
        end
        return Create("UICorner", {
            Parent = Parent,
            CornerRadius = UDim.new(0, Value)
        })
    end

