    local ActiveTweens = setmetatable({}, { __mode = "k" })

    local function Tween(Object, Duration, Properties)
        if not Object or not Object.Parent or type(Properties) ~= "table" then return nil end
        local Previous = ActiveTweens[Object]
        if Previous then Library.Call(function() Previous:Cancel() end) end
        local RequestedDuration = (tonumber(Duration) or 0.08) / math.max(AnimationFactor, 0.05)
        local EffectiveDuration = math.clamp(RequestedDuration, 0.015, 0.055)
        local Animation = TweenService:Create(
            Object,
            TweenInfo.new(EffectiveDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            Properties
        )
        ActiveTweens[Object] = Animation
        Animation:Play()

        local CompletionConnection
        CompletionConnection = Animation.Completed:Connect(function()
            if CompletionConnection then
                CompletionConnection:Disconnect()
                CompletionConnection = nil
            end
            if ActiveTweens[Object] == Animation then ActiveTweens[Object] = nil end
        end)
        return Animation
    end

    local function SmoothSlider(FrameObject, KnobObject, Alpha, Duration)
        Alpha = math.clamp(Alpha or 0, 0, 1)
        if FrameObject then
            Tween(FrameObject, Duration or 0.12, {Size = UDim2.new(Alpha, 0, 1, 0)})
        end
        if KnobObject then
            Tween(KnobObject, Duration or 0.12, {Position = UDim2.new(Alpha, 0, 0.5, 0)})
        end
    end

