    local function CreateSlider(Section, Name, Minimum, Maximum, Default, Flag, Options)
        Options = Options or {}
        local Step = math.max(math.abs(tonumber(Options.Step) or 1), 0.000001)
        local Decimals = tonumber(Options.Decimals)
        if Decimals == nil then
            local StepText = string.format("%.8f", Step):gsub("0+$", ""):gsub("%.$", "")
            local Dot = string.find(StepText, ".", 1, true)
            Decimals = Dot and math.min(6, #StepText - Dot) or 0
        else
            Decimals = math.max(0, math.floor(Decimals + 0.5))
        end
        local Row = CreateRow(Section.Body, 36)

        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(1, -52, 0, 15),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = Options.Disabled and DisabledText or PrimaryText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 8
        })

        if Options.Gear then
            CreateGear(Row, -43, 9, Name, Flag, {Type = "Number", Minimum = Minimum, Maximum = Maximum, Decimals = Decimals, Step = Step})
        end

        local Prefix = tostring(Options.Prefix or "")
        local Suffix = tostring(Options.Suffix or "")
        local ValueLabel
        if Options.Box then
            local BoxWidth = math.max(46, 34 + (#Prefix + #Suffix) * 4)
            ValueLabel = CreateValueBox(Row, tostring(Default), 0, BoxWidth)
        else
            ValueLabel = Create("TextLabel", {
                Parent = Row,
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 0, 0, 0),
                Size = UDim2.fromOffset(math.max(48, 34 + (#Prefix + #Suffix) * 4), 18),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSans,
                Text = tostring(Default),
                TextColor3 = MutedText,
                TextSize = 10,
                TextXAlignment = Enum.TextXAlignment.Right,
                ZIndex = 8
            })
        end

        local Track = Create("Frame", {
            Parent = Row,
            Position = UDim2.fromOffset(0, 25),
            Size = UDim2.new(1, 0, 0, 3),
            Active = true,
            BackgroundColor3 = Border,
            BorderSizePixel = 0,
            ZIndex = 8
        })
        Corner(Track, 0)

        local Fill = Create("Frame", {
            Parent = Track,
            Size = UDim2.new((Default - Minimum) / (Maximum - Minimum), 0, 1, 0),
            BackgroundColor3 = Accent,
            BorderSizePixel = 0,
            ZIndex = 9
        })
        Corner(Fill, 0)
        local FillGlow = Menu:AddSoftGlow(Fill, 9, 8, 0.62, true)

        local Knob = Create("Frame", {
            Parent = Track,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new((Default - Minimum) / (Maximum - Minimum), 0, 0.5, 0),
            Size = UDim2.fromOffset(2, 7),
            BackgroundColor3 = Accent,
            BorderSizePixel = 0,
            ZIndex = 10
        })
        Corner(Knob, 0)
        local KnobGlow = Menu:AddSoftGlow(Knob, 10, 7, 0.24, false)
        local Value = Default
        local Dragging = false
        RegisterAccentTarget(function(NewColor)
            Fill.BackgroundColor3 = NewColor
            if FillGlow then
                FillGlow.ImageColor3 = NewColor
            end
            if KnobGlow then
                KnobGlow.ImageColor3 = NewColor
            end
        end)
        Bind(Track.MouseEnter:Connect(function()
            Tween(Knob, 0.08, {Size = UDim2.fromOffset(2, 7)})
            if FillGlow then
                Tween(FillGlow, 0.12, {ImageTransparency = 0.52})
            end
            if KnobGlow then
                Tween(KnobGlow, 0.12, {ImageTransparency = 0.14})
            end
        end))
        Bind(Track.MouseLeave:Connect(function()
            if not Dragging then
                Tween(Knob, 0.08, {Size = UDim2.fromOffset(2, 7)})
                if FillGlow then
                    Tween(FillGlow, 0.12, {ImageTransparency = 0.62})
                end
                if KnobGlow then
                    Tween(KnobGlow, 0.12, {ImageTransparency = 0.24})
                end
            end
        end))
        Menu.Flags[Flag] = Value

        local function FormatNumber(Number)
            if Decimals > 0 then
                local Formatted = string.format("%." .. tostring(Decimals) .. "f", Number)
                return Formatted:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
            end
            return tostring(math.floor(Number + 0.5))
        end

        local function Format(Number)
            return Prefix .. FormatNumber(Number) .. Suffix
        end

        local function Parse(TextValue)
            local Parsed = tostring(TextValue or ""):gsub(",", ".")
            if Prefix ~= "" and Parsed:sub(1, #Prefix) == Prefix then
                Parsed = Parsed:sub(#Prefix + 1)
            end
            if Suffix ~= "" and Parsed:sub(-#Suffix) == Suffix then
                Parsed = Parsed:sub(1, #Parsed - #Suffix)
            end
            Parsed = Parsed:match("[-+]?%d*%.?%d+")
            return tonumber(Parsed)
        end

        local function Set(NewValue)
            NewValue = math.clamp(tonumber(NewValue) or Value, Minimum, Maximum)
            NewValue = Minimum + math.floor(((NewValue - Minimum) / Step) + 0.5) * Step
            NewValue = math.clamp(NewValue, Minimum, Maximum)
            local Power = 10 ^ Decimals
            NewValue = math.floor(NewValue * Power + 0.5) / Power
            Value = NewValue
            Menu.Flags[Flag] = Value
            local Alpha = (Value - Minimum) / (Maximum - Minimum)
            SmoothSlider(Fill, Knob, Alpha, 0.12)
            ValueLabel.Text = Format(Value)
            if type(Options.Callback) == "function" then
                task.spawn(Options.Callback, Value)
            end
        end

        Menu.Setters[Flag] = Set
        ValueLabel.Text = Format(Value)

        if Options.Box and ValueLabel:IsA("TextBox") then
            Bind(ValueLabel.Focused:Connect(function()
                ValueLabel.Text = FormatNumber(Value)
            end))
            Bind(ValueLabel.FocusLost:Connect(function()
                local Parsed = Parse(ValueLabel.Text)
                if Parsed ~= nil then
                    Set(Parsed)
                else
                    ValueLabel.Text = Format(Value)
                end
            end))
        end

        local function Update(Input)
            local Alpha = math.clamp((Input.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
            Set(Minimum + (Maximum - Minimum) * Alpha)
        end

        Bind(Track.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = true
                Update(Input)
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                Update(Input)
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = false
            end
        end))

        RegisterControl(Section, Row, Name)
        return {
            Row = Row,
            Set = Set,
            Get = function()
                return Value
            end
        }
    end

    local function CreateDualSlider(Section, Name, Minimum, Maximum, DefaultMinimum, DefaultMaximum, MinimumFlag, MaximumFlag, Options)
        Options = Options or {}
        local Row = CreateRow(Section.Body, 51)
        local Prefix = tostring(Options.Prefix or "")
        local Suffix = tostring(Options.Suffix or "")
        local Step = math.max(math.abs(tonumber(Options.Step) or 1), 0.000001)
        local Decimals = tonumber(Options.Decimals)
        if Decimals == nil then
            local StepText = string.format("%.8f", Step):gsub("0+$", ""):gsub("%.$", "")
            local Dot = string.find(StepText, ".", 1, true)
            Decimals = Dot and math.min(6, #StepText - Dot) or 0
        else
            Decimals = math.max(0, math.floor(Decimals + 0.5))
        end

        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(1, -128, 0, 20),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = Options.Disabled and DisabledText or PrimaryText,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 8
        })

        if Options.Gear ~= false then
            CreateGear(Row, -86, 10, Name, MinimumFlag, {Type = "Number", Minimum = Minimum, Maximum = Maximum, Decimals = Decimals, Step = Step})
        end

        local MinimumLabel = CreateValueBox(Row, tostring(DefaultMinimum), -51, 44)
        local MaximumLabel = CreateValueBox(Row, tostring(DefaultMaximum), 0, 44)

        local Track = Create("Frame", {
            Parent = Row,
            Position = UDim2.fromOffset(0, 35),
            Size = UDim2.new(1, 0, 0, 4),
            BackgroundColor3 = Border,
            BorderSizePixel = 0,
            ZIndex = 8
        })
        Corner(Track, 2)

        local function Round(Value)
            Value = math.clamp(tonumber(Value) or Minimum, Minimum, Maximum)
            Value = Minimum + math.floor(((Value - Minimum) / Step) + 0.5) * Step
            Value = math.clamp(Value, Minimum, Maximum)
            local Power = 10 ^ Decimals
            return math.floor(Value * Power + 0.5) / Power
        end

        local function FormatNumber(Value)
            if Decimals > 0 then
                local Result = string.format("%." .. tostring(Decimals) .. "f", Value)
                return Result:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
            end
            return tostring(math.floor(Value + 0.5))
        end

        local function Format(Value)
            return Prefix .. FormatNumber(Value) .. Suffix
        end

        local function Parse(Value)
            local Result = tostring(Value or ""):gsub(",", ".")
            if Prefix ~= "" and Result:sub(1, #Prefix) == Prefix then
                Result = Result:sub(#Prefix + 1)
            end
            if Suffix ~= "" and Result:sub(-#Suffix) == Suffix then
                Result = Result:sub(1, #Result - #Suffix)
            end
            Result = Result:match("[-+]?%d*%.?%d+")
            return tonumber(Result)
        end

        local Low = Round(DefaultMinimum)
        local High = Round(DefaultMaximum)
        if Low > High then Low, High = High, Low end

        local MinimumAlpha = (Low - Minimum) / math.max(Maximum - Minimum, 0.0001)
        local MaximumAlpha = (High - Minimum) / math.max(Maximum - Minimum, 0.0001)

        local Fill = Create("Frame", {
            Parent = Track,
            Position = UDim2.new(MinimumAlpha, 0, 0, 0),
            Size = UDim2.new(MaximumAlpha - MinimumAlpha, 0, 1, 0),
            BackgroundColor3 = Accent,
            BorderSizePixel = 0,
            ZIndex = 9
        })
        Corner(Fill, 2)
        local FillGlow = Menu:AddSoftGlow(Fill, 9, 8, 0.62, true)

        local MinimumKnob = Create("Frame", {
            Parent = Track,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(MinimumAlpha, 0, 0.5, 0),
            Size = UDim2.fromOffset(6, 14),
            BackgroundColor3 = Color3.fromRGB(220, 220, 224),
            BorderSizePixel = 0,
            ZIndex = 10
        })
        Corner(MinimumKnob, 2)

        local MaximumKnob = Create("Frame", {
            Parent = Track,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(MaximumAlpha, 0, 0.5, 0),
            Size = UDim2.fromOffset(6, 14),
            BackgroundColor3 = Color3.fromRGB(220, 220, 224),
            BorderSizePixel = 0,
            ZIndex = 10
        })
        Corner(MaximumKnob, 2)
        local MinimumGlow = Menu:AddSoftGlow(MinimumKnob, 10, 7, 0.24, false)
        local MaximumGlow = Menu:AddSoftGlow(MaximumKnob, 10, 7, 0.24, false)
        RegisterAccentTarget(function(NewColor)
            Fill.BackgroundColor3 = NewColor
            if FillGlow then FillGlow.ImageColor3 = NewColor end
            if MinimumGlow then MinimumGlow.ImageColor3 = NewColor end
            if MaximumGlow then MaximumGlow.ImageColor3 = NewColor end
        end)

        local ActiveKnob
        Menu.Flags[MinimumFlag] = Low
        Menu.Flags[MaximumFlag] = High

        local function Refresh(Invoke)
            local LowAlpha = (Low - Minimum) / math.max(Maximum - Minimum, 0.0001)
            local HighAlpha = (High - Minimum) / math.max(Maximum - Minimum, 0.0001)
            MinimumKnob.Position = UDim2.new(LowAlpha, 0, 0.5, 0)
            MaximumKnob.Position = UDim2.new(HighAlpha, 0, 0.5, 0)
            Fill.Position = UDim2.new(LowAlpha, 0, 0, 0)
            Fill.Size = UDim2.new(HighAlpha - LowAlpha, 0, 1, 0)
            MinimumLabel.Text = Format(Low)
            MaximumLabel.Text = Format(High)
            Menu.Flags[MinimumFlag] = Low
            Menu.Flags[MaximumFlag] = High
            if Invoke and type(Options.Callback) == "function" then
                task.spawn(Options.Callback, Low, High)
            end
        end

        local function SetMinimum(Value, Invoke)
            Low = math.clamp(Round(Value), Minimum, High)
            Refresh(Invoke ~= false)
        end

        local function SetMaximum(Value, Invoke)
            High = math.clamp(Round(Value), Low, Maximum)
            Refresh(Invoke ~= false)
        end

        Bind(MinimumLabel.Focused:Connect(function()
            MinimumLabel.Text = FormatNumber(Low)
        end))
        Bind(MaximumLabel.Focused:Connect(function()
            MaximumLabel.Text = FormatNumber(High)
        end))
        Bind(MinimumLabel.FocusLost:Connect(function()
            local Parsed = Parse(MinimumLabel.Text)
            if Parsed ~= nil then
                SetMinimum(Parsed)
            else
                MinimumLabel.Text = Format(Low)
            end
        end))
        Bind(MaximumLabel.FocusLost:Connect(function()
            local Parsed = Parse(MaximumLabel.Text)
            if Parsed ~= nil then
                SetMaximum(Parsed)
            else
                MaximumLabel.Text = Format(High)
            end
        end))

        Menu.Setters[MinimumFlag] = SetMinimum
        Menu.Setters[MaximumFlag] = SetMaximum

        local function Update(Input)
            local Alpha = math.clamp((Input.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
            local Value = Minimum + (Maximum - Minimum) * Alpha
            if ActiveKnob == MinimumKnob then
                SetMinimum(math.min(Value, High))
            else
                SetMaximum(math.max(Value, Low))
            end
        end

        local function Begin(Input, Knob)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                ActiveKnob = Knob
                Update(Input)
            end
        end

        Bind(MinimumKnob.InputBegan:Connect(function(Input)
            Begin(Input, MinimumKnob)
        end))
        Bind(MaximumKnob.InputBegan:Connect(function(Input)
            Begin(Input, MaximumKnob)
        end))
        Bind(Track.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                local Alpha = math.clamp((Input.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
                local Value = Minimum + (Maximum - Minimum) * Alpha
                ActiveKnob = math.abs(Value - Low) <= math.abs(Value - High) and MinimumKnob or MaximumKnob
                Update(Input)
            end
        end))
        Bind(UserInputService.InputChanged:Connect(function(Input)
            if ActiveKnob and Input.UserInputType == Enum.UserInputType.MouseMovement then
                Update(Input)
            end
        end))
        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                ActiveKnob = nil
            end
        end))

        Refresh(false)
        RegisterControl(Section, Row, Name)
        return {
            Row = Row,
            SetMinimum = SetMinimum,
            SetMaximum = SetMaximum,
            Get = function()
                return Low, High
            end
        }
    end

    local ActivePopup
    local ActivePopupCleanup

    local function ClosePopup()
        if ActivePopupCleanup then
            Library.Call(
                ActivePopupCleanup
            )

            ActivePopupCleanup =
                nil
        end

        if ActivePopup then
            ActivePopup:Destroy()
            ActivePopup = nil
        end

        if Menu.RefreshDropdownIndicators then
            Menu.RefreshDropdownIndicators(
                true
            )
        end

        if not ActiveGearMenu then
            Menu.PopupInputBlocker.Visible =
                false
        end
    end

    local function SetGearIconColor(IconObject, Color)
        if not IconObject then
            return
        end
        Library.Call(function()
            if IconObject:IsA("ImageLabel") or IconObject:IsA("ImageButton") then
                IconObject.ImageColor3 = Color
                return
            end
        end)
        for _, Descendant in ipairs(IconObject:GetDescendants()) do
            if Descendant:IsA("ImageLabel") or Descendant:IsA("ImageButton") then
                Descendant.ImageColor3 = Color
            elseif Descendant:IsA("Frame") and Descendant.BackgroundTransparency < 1 then
                Descendant.BackgroundColor3 = Color
            elseif Descendant:IsA("UIStroke") then
                Descendant.Color = Color
            end
        end
    end

    Menu.ClampPopupPosition = function(FrameObject, Position)
        if not FrameObject then return Position end
        Position = typeof(Position) == "UDim2" and Position or FrameObject.Position
        local Camera = workspace.CurrentCamera
        local Viewport = Camera and Camera.ViewportSize or Vector2.new(1920, 1080)
        local Size = FrameObject.AbsoluteSize
        if Size.X <= 0 or Size.Y <= 0 then
            Size = Vector2.new(FrameObject.Size.X.Offset, FrameObject.Size.Y.Offset)
        end
        local X = Position.X.Scale * Viewport.X + Position.X.Offset
        local Y = Position.Y.Scale * Viewport.Y + Position.Y.Offset
        X = math.clamp(X, 8, math.max(8, Viewport.X - Size.X - 8))
        Y = math.clamp(Y, 8, math.max(8, Viewport.Y - Size.Y - 8))
        return UDim2.fromOffset(math.floor(X + 0.5), math.floor(Y + 0.5))
    end

