    local function FriendlyKeyName(Name)
        local Raw =
            tostring(
                Name or "Unknown"
            )

        local Canonical =
            BindKeyCanonical[Raw]
            or Raw

        local Alias =
            BindKeyAliases[Canonical]

        if Alias then
            return Alias
        end

        local Result =
            Canonical:
                gsub(
                    "(%l)(%u)",
                    "%1 %2"
                )

        return string.upper(
            Result
        )
    end

    local function BuildBindDisplay(KeyName, Modifiers)
        local Parts = {}

        if Modifiers
            and Modifiers.Ctrl
        then
            table.insert(
                Parts,
                "CTRL"
            )
        end

        if Modifiers
            and Modifiers.Shift
        then
            table.insert(
                Parts,
                "SHIFT"
            )
        end

        if Modifiers
            and Modifiers.Alt
        then
            table.insert(
                Parts,
                "ALT"
            )
        end

        table.insert(
            Parts,
            FriendlyKeyName(
                KeyName
            )
        )

        return table.concat(
            Parts,
            " + "
        )
    end

    local function GetInputIdentity(Input)
        if not Input then
            return nil, nil
        end

        local InputType =
            Input.UserInputType

        local InputTypeName =
            InputType
            and InputType.Name
            or ""

        local KeyCode =
            Input.KeyCode

        local KeyCodeName =
            KeyCode
            and KeyCode.Name
            or ""

        if type(InputTypeName) == "string"
            and string.match(
                InputTypeName,
                "^MouseButton%d+$"
            )
        then
            if InputTypeName
                == "MouseButton1"
            then
                return nil, nil
            end

            return Menu.BindSystem.CanonicalBindKey(
                "UserInputType",
                InputTypeName
            )
        end

        if type(KeyCodeName) == "string"
            and KeyCodeName ~= ""
            and KeyCodeName ~= "Unknown"
        then
            local CanonicalType,
                CanonicalName =
                Menu.BindSystem.CanonicalBindKey(
                    "KeyCode",
                    KeyCodeName
                )

            if CanonicalName
                == "MouseButton1"
            then
                return nil, nil
            end

            return CanonicalType,
                CanonicalName
        end

        if type(InputTypeName) == "string"
            and InputTypeName ~= ""
            and InputTypeName ~= "Keyboard"
            and InputTypeName ~= "MouseMovement"
            and InputTypeName ~= "MouseWheel"
            and InputTypeName ~= "Touch"
            and InputTypeName ~= "None"
        then
            local CanonicalType,
                CanonicalName =
                Menu.BindSystem.CanonicalBindKey(
                    "UserInputType",
                    InputTypeName
                )

            if CanonicalName
                ~= InputTypeName
                or string.match(
                    CanonicalName,
                    "^MouseButton%d+$"
                )
            then
                return CanonicalType,
                    CanonicalName
            end
        end

        return nil, nil
    end

    local function ModifiersEqual(Expected)
        Expected = Expected or {}
        local Current = ReadModifiers()
        return Current.Ctrl == (Expected.Ctrl == true)
            and Current.Shift == (Expected.Shift == true)
            and Current.Alt == (Expected.Alt == true)
    end

    local function BindMatchesInput(BindData, Input, CheckModifiers)
        if type(BindData) ~= "table" then
            return false
        end

        local KeyType,
            KeyName =
            GetInputIdentity(
                Input
            )

        if not KeyType
            or not KeyName
        then
            return false
        end

        local StoredType,
            StoredName =
            Menu.BindSystem.CanonicalBindKey(
                BindData.KeyType,
                BindData.Key
            )

        if StoredType ~= KeyType
            or StoredName ~= KeyName
        then
            return false
        end

        if CheckModifiers == false then
            return true
        end

        return ModifiersEqual(
            BindData.Modifiers
        )
    end

    local function FormatBindLabel(BindData)
        local Display = BuildBindDisplay(BindData.Key, BindData.Modifiers)
        BindData.Display = Display
        return Display .. "   |   " .. tostring(BindData.Mode or "Toggle")
    end

    local function AddPopupShadow(Target, ZIndex)
        return Menu:AddSoftGlow(Target, ZIndex, 9, 0.64, true)
    end

    local function RectsOverlap(A, B)
        if not A or not B or not A.Parent or not B.Parent then
            return false
        end
        local AP, AS = A.AbsolutePosition, A.AbsoluteSize
        local BP, BS = B.AbsolutePosition, B.AbsoluteSize
        return AP.X < BP.X + BS.X and AP.X + AS.X > BP.X and AP.Y < BP.Y + BS.Y and AP.Y + AS.Y > BP.Y
    end

    local function PointInside(Object, Position)
        if not Object or not Object.Parent or not Position then
            return false
        end
        local ObjectPosition = Object.AbsolutePosition
        local ObjectSize = Object.AbsoluteSize
        return Position.X >= ObjectPosition.X and Position.X <= ObjectPosition.X + ObjectSize.X
            and Position.Y >= ObjectPosition.Y and Position.Y <= ObjectPosition.Y + ObjectSize.Y
    end

    local function PlacePopup(FrameObject, PreferredPosition, Peers)
        local Position = Menu.ClampPopupPosition(FrameObject, PreferredPosition)
        FrameObject.Position = Position
        for _, Peer in ipairs(Peers or {}) do
            if Peer and Peer.Parent and RectsOverlap(FrameObject, Peer) then
                local Gap = 8
                local Candidates = {
                    UDim2.fromOffset(Peer.AbsolutePosition.X + Peer.AbsoluteSize.X + Gap, Position.Y.Offset),
                    UDim2.fromOffset(Peer.AbsolutePosition.X - FrameObject.AbsoluteSize.X - Gap, Position.Y.Offset),
                    UDim2.fromOffset(Position.X.Offset, Peer.AbsolutePosition.Y + Peer.AbsoluteSize.Y + Gap),
                    UDim2.fromOffset(Position.X.Offset, Peer.AbsolutePosition.Y - FrameObject.AbsoluteSize.Y - Gap)
                }
                for _, Candidate in ipairs(Candidates) do
                    local CandidatePosition = Menu.ClampPopupPosition(FrameObject, Candidate)
                    FrameObject.Position = CandidatePosition
                    if not RectsOverlap(FrameObject, Peer) then
                        Position = CandidatePosition
                        break
                    end
                end
            end
        end
        return FrameObject.Position
    end

    local function MakePopupDraggable(FrameObject, Height)
        local Handle = Create("TextButton", {
            Parent = FrameObject,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(1, 0, 0, Height or 14),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            Active = true,
            ZIndex = FrameObject.ZIndex + 20
        })

        local Grip = Create("Frame", {
            Parent = Handle,
            AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 5),
            Size = UDim2.fromOffset(24, 2),
            BackgroundColor3 = Border,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            ZIndex = Handle.ZIndex + 1
        })
        Corner(Grip, 2)

        local Dragging = false
        local DragStart
        local StartPosition

        Bind(Handle.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = true
                DragStart = Input.Position
                StartPosition = FrameObject.Position
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                local Delta = Input.Position - DragStart
                FrameObject.Position = Menu.ClampPopupPosition(FrameObject, UDim2.fromOffset(StartPosition.X.Offset + Delta.X, StartPosition.Y.Offset + Delta.Y))
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = false
            end
        end))
    end

    local function CreateGlyph(ParentObject, Kind, Color, Position)
        local Root = Create("Frame", {
            Parent = ParentObject,
            Position = Position or UDim2.fromOffset(10, 8),
            Size = UDim2.fromOffset(12, 12),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = ParentObject.ZIndex + 2
        })

        local function Line(X, Y, W, H)
            local Object = Create("Frame", {
                Parent = Root,
                Position = UDim2.fromOffset(X, Y),
                Size = UDim2.fromOffset(W, H),
                BackgroundColor3 = Color,
                BorderSizePixel = 0,
                ZIndex = Root.ZIndex + 1
            })
            Corner(Object, 2)
            return Object
        end

        local function Outline(X, Y, W, H)
            local Object = Create("Frame", {
                Parent = Root,
                Position = UDim2.fromOffset(X, Y),
                Size = UDim2.fromOffset(W, H),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = Root.ZIndex + 1
            })
            Corner(Object, 2)
            Stroke(Object, Color, 0, 1)
            return Object
        end

        if Kind == "Bind" then
            Outline(1, 3, 10, 7)
            Line(3, 5, 6, 1)
            Line(2, 7, 1, 1)
            Line(4, 7, 1, 1)
            Line(6, 7, 1, 1)
            Line(8, 7, 1, 1)
            Line(10, 7, 1, 1)
            Line(2, 9, 2, 1)
            Line(5, 9, 3, 1)
            Line(9, 9, 2, 1)
        elseif Kind == "Hotkeys" then
            Line(1, 2, 10, 1)
            Line(1, 6, 10, 1)
            Line(1, 10, 10, 1)
            Line(3, 0, 2, 4)
            Line(7, 4, 2, 4)
            Line(4, 8, 2, 4)
        elseif Kind == "Reset" then
            Line(2, 3, 8, 1)
            Line(5, 1, 2, 1)
            Outline(3, 4, 6, 7)
            Line(5, 6, 1, 3)
            Line(7, 6, 1, 3)
        end
        return Root
    end

    local function CreateMenuEntry(ParentObject, Y, TextValue, GlyphKind, TextColor, Arrow)
        local Entry = Create("TextButton", {
            Parent = ParentObject,
            Position = UDim2.fromOffset(7, Y),
            Size = UDim2.new(1, -14, 0, 27),
            BackgroundColor3 = SurfaceAlt,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = ParentObject.ZIndex + 2
        })
        Corner(Entry, 5)
        local EntryScale = Create("UIScale", {Parent = Entry, Scale = 1})
        local Glyph = CreateGlyph(Entry, GlyphKind, TextColor, UDim2.fromOffset(8, 7))

        local Label = Create("TextLabel", {
            Parent = Entry,
            Position = UDim2.fromOffset(28, 0),
            Size = UDim2.new(1, Arrow and -44 or -34, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = TextValue,
            TextColor3 = TextColor,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = Entry.ZIndex + 2
        })

        local ArrowIcon
        if Arrow then
            ArrowIcon = Icon(Entry, "Chevron", UDim2.fromOffset(8, 8), UDim2.new(1, -10, 0.5, 0), TextColor, Entry.ZIndex + 2)
            ArrowIcon.Rotation = -90
        end

        local Hovered = false
        local Pressed = false
        local function RefreshEntry()
            if not Entry.Parent then return end
            local Selected = Entry:GetAttribute("Selected") == true
            local Active = Selected or Hovered
            local ActiveText = GlyphKind == "Reset" and Danger or (Active and PrimaryText or TextColor)
            local ActiveGlyph = GlyphKind == "Reset" and Danger or (Active and Accent or TextColor)
            Tween(Entry, 0.10, {
                BackgroundTransparency = Selected and 0.18 or (Hovered and 0.42 or 1),
                BackgroundColor3 = Selected and Accent:Lerp(SurfaceAlt, 0.78) or SurfaceAlt
            })
            Tween(Label, 0.10, {TextColor3 = ActiveText})
            SetGearIconColor(Glyph, ActiveGlyph)
            if ArrowIcon then Tween(ArrowIcon, 0.10, {ImageColor3 = ActiveGlyph}) end
            EntryScale.Scale = 1
        end

        RegisterAccentTarget(function()
            RefreshEntry()
        end)

        Bind(Entry.MouseEnter:Connect(function()
            Hovered = true
            RefreshEntry()
        end))
        Bind(Entry.MouseLeave:Connect(function()
            Hovered = false
            Pressed = false
            RefreshEntry()
        end))
        Bind(Entry.MouseButton1Down:Connect(function()
            Pressed = true
            RefreshEntry()
        end))
        Bind(Entry.MouseButton1Up:Connect(function()
            Pressed = false
            RefreshEntry()
        end))
        Bind(Entry:GetAttributeChangedSignal("Selected"):Connect(RefreshEntry))
        RefreshEntry()
        return Entry
    end

    local function SetEntrySelected(Entry, State)
        if not Entry or not Entry.Parent then return end
        Entry:SetAttribute("Selected", State and true or false)
    end

    local function AttachBindButtonHover(Button, RefreshVisual)
        local State = {Hovered = false, Pressed = false}
        local Scale = Button:FindFirstChildWhichIsA("UIScale") or Create("UIScale", {Parent = Button, Scale = 1})
        local function Refresh()
            if not Button or not Button.Parent then return end
            if type(RefreshVisual) == "function" then RefreshVisual(State) end
            Scale.Scale = 1
        end
        RegisterAccentTarget(function()
            Refresh()
        end)
        Bind(Button.MouseEnter:Connect(function()
            State.Hovered = true
            Refresh()
        end))
        Bind(Button.MouseLeave:Connect(function()
            State.Hovered = false
            State.Pressed = false
            Refresh()
        end))
        Bind(Button.MouseButton1Down:Connect(function()
            State.Pressed = true
            Refresh()
        end))
        Bind(Button.MouseButton1Up:Connect(function()
            State.Pressed = false
            Refresh()
        end))
        Refresh()
        return State, Refresh
    end

