    local function FindEnumItem(EnumType, Names)
        local Wanted = {}

        for _, Name in ipairs(Names) do
            Wanted[Name] = true
        end

        for _, Item in ipairs(
            EnumType:GetEnumItems()
        ) do
            if Wanted[Item.Name] then
                return Item
            end
        end

        return nil
    end

