    function Menu.BindSystem.GetCustomMouseStates()
        local States = Menu.BindSystem.CustomMouse.States
        States.MouseButton4 = false
        States.MouseButton5 = false

        for _, Input in ipairs(
            UserInputService:
                GetMouseButtonsPressed()
        ) do
            local KeyType,
                KeyName =
                Menu.BindSystem.
                    GetInputIdentity(
                        Input
                    )

            if KeyType
                and (
                    KeyName == "MouseButton4"
                    or KeyName == "MouseButton5"
                )
            then
                States[KeyName] = true
            end
        end

        for _, Input in ipairs(
            UserInputService:
                GetKeysPressed()
        ) do
            local KeyType,
                KeyName =
                Menu.BindSystem.
                    GetInputIdentity(
                        Input
                    )

            if KeyType
                and (
                    KeyName == "MouseButton4"
                    or KeyName == "MouseButton5"
                )
            then
                States[KeyName] = true
            end
        end

        for KeyName, KeyCode in pairs(
            Menu.BindSystem.CustomMouse.KeyCodes
        ) do
            if KeyCode
                and UserInputService:
                    IsKeyDown(
                        KeyCode
                    )
            then
                States[KeyName] = true
            end
        end

        for KeyName, InputType in pairs(
            Menu.BindSystem.CustomMouse.InputTypes
        ) do
            if InputType
                and UserInputService:
                    IsMouseButtonPressed(
                        InputType
                    )
            then
                States[KeyName] = true
            end
        end

        return States
    end

    function Menu.BindSystem.BindMatchesIdentity(
        BindData,
        KeyType,
        KeyName,
        CheckModifiers
    )
        if type(BindData) ~= "table" then
            return false
        end

        local StoredType,
            StoredName =
            Menu.BindSystem.
                CanonicalBindKey(
                    BindData.KeyType,
                    BindData.Key
                )

        KeyType,
            KeyName =
            Menu.BindSystem.
                CanonicalBindKey(
                    KeyType,
                    KeyName
                )

        if StoredType ~= KeyType
            or StoredName ~= KeyName
        then
            return false
        end

        if CheckModifiers == false then
            return true
        end

        return ModifiersEqual(
            BindData.Modifiers
        )
    end
    end

    Menu.DropdownIndicators =
