    function Menu.RefreshDropdownIndicators(CloseAll)
        local Dead = {}

        for Indicator in pairs(
            Menu.DropdownIndicators
        ) do
            if not Indicator
                or not Indicator.Root
                or not Indicator.Root.Parent
            then
                Dead[#Dead + 1] =
                    Indicator
            else
                if CloseAll == true then
                    Indicator.Opened =
                        false
                end

                Indicator:SetAccentColor(
                    Accent
                )

                Indicator:Refresh(
                    false
                )
            end
        end

        for _, Indicator in ipairs(
            Dead
        ) do
            Menu.DropdownIndicators[
                Indicator
            ] = nil
        end
    end

    Menu.CreateDropdownExpandIndicator = function(Button, ZIndex)
        for _, Child in ipairs(
            Button:GetChildren()
        ) do
            if Child.Name
                    == "AtramentaDropdownIndicator"
                and Child:IsA("Frame")
            then
                Child:Destroy()
            end
        end

        local Root = Create("Frame", {
            Name = "AtramentaDropdownIndicator",
            Parent = Button,
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -8, 0.5, 0),
            Size = UDim2.fromOffset(12, 12),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = ZIndex or 11
        })

        local Horizontal = Create("Frame", {
            Name = "Horizontal",
            Parent = Root,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(8, 1),
            BackgroundColor3 = Accent,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            ZIndex = (ZIndex or 11) + 1
        })
        Corner(Horizontal, 1)

        local Vertical = Create("Frame", {
            Name = "Vertical",
            Parent = Root,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(1, 8),
            BackgroundColor3 = Accent,
            BackgroundTransparency = 0,
            BorderSizePixel = 0,
            ZIndex = (ZIndex or 11) + 1
        })
        Corner(Vertical, 1)

        local Indicator = {
            Root = Root,
            Horizontal = Horizontal,
            Vertical = Vertical,
            Opened = false,
            AccentColor = Accent
        }

        function Indicator:Refresh(AnimateTransparency)
            if not self.Root
                or not self.Root.Parent
            then
                return
            end

            local CurrentAccent =
                typeof(self.AccentColor)
                    == "Color3"
                and self.AccentColor
                or Accent

            self.Horizontal.BackgroundColor3 =
                CurrentAccent

            self.Vertical.BackgroundColor3 =
                CurrentAccent

            self.Vertical.Visible =
                not self.Opened

            if AnimateTransparency == true then
                Tween(
                    self.Horizontal,
                    0.10,
                    {
                        BackgroundTransparency =
                            self.Opened
                            and 0
                            or 0.12
                    }
                )

                Tween(
                    self.Vertical,
                    0.10,
                    {
                        BackgroundTransparency = 0
                    }
                )
            else
                self.Horizontal.BackgroundTransparency =
                    self.Opened
                    and 0
                    or 0.12

                self.Vertical.BackgroundTransparency =
                    0
            end
        end

        function Indicator:SetOpened(State)
            self.Opened =
                State == true

            self:Refresh(
                true
            )
        end

        function Indicator:SetAccentColor(NewColor)
            if typeof(NewColor)
                ~= "Color3"
            then
                return
            end

            self.AccentColor =
                NewColor

            self:Refresh(
                false
            )
        end

        Menu.DropdownIndicators[
            Indicator
        ] = true

        RegisterAccentTarget(function(NewColor)
            if not Root
                or not Root.Parent
            then
                Menu.DropdownIndicators[
                    Indicator
                ] = nil

                return
            end

            Indicator:SetAccentColor(
                NewColor
            )
        end)

        Indicator:SetAccentColor(
            Accent
        )

        Indicator.Opened = false
        Indicator:Refresh(false)

        return Indicator
    end

    local function CreateDropdown(Section, Name, Values, Default, Flag, Options)
        Options = Options or {}
        Values = type(Values) == "table" and Values or {}
        local Row = CreateRow(Section.Body, 22)

        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(0.54, 0, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = Options.Disabled and DisabledText or PrimaryText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 8
        })

        if Options.Gear then
            CreateGear(Row, -150, 11, Name, Flag, {Type = "Dropdown", Values = Values})
        end

        local Current = Default
        local IsOpened = false
        Menu.Flags[Flag] = Current

        local Button = Create("TextButton", {
            Parent = Row,
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.fromOffset(140, 18),
            BackgroundColor3 = SurfaceAlt,
            BackgroundTransparency = 0,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 9
        })
