        local ButtonStroke = Stroke(Button, Border, 0, 1)

        RegisterAccentTarget(function(NewColor)
            if not ButtonStroke
                or not ButtonStroke.Parent
            then
                return
            end

            ButtonStroke.Color =
                IsOpened
                and NewColor
                or Border
        end)

        local ValueLabel = Create("TextLabel", {
            Parent = Button,
            Position = UDim2.fromOffset(6, 0),
            Size = UDim2.new(1, -30, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = tostring(Default),
            TextColor3 = PrimaryText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 10,
            TextTruncate = Enum.TextTruncate.AtEnd
        })



        local ExpandIndicator =
            Menu.CreateDropdownExpandIndicator(
                Button,
                11
            )

        local function Set(Value)
            Current = Value
            Menu.Flags[Flag] = Value
            ValueLabel.Text = tostring(Value)
            ClosePopup()

            if type(Options.Callback) == "function" then
                task.spawn(Options.Callback, Value)
            end
        end

        Menu.Setters[Flag] = Set

        Bind(Button.MouseEnter:Connect(function()
            if not IsOpened then
                Tween(Button, 0.10, {
                    BackgroundTransparency = 0.10
                })
                Tween(ButtonStroke, 0.10, {
                    Color = Color3.fromRGB(45, 61, 69)
                })
            end
        end))

        Bind(Button.MouseLeave:Connect(function()
            if not IsOpened then
                Tween(Button, 0.10, {
                    BackgroundTransparency = 0.22
                })
                Tween(ButtonStroke, 0.10, {
                    Color = Border
                })
            end
        end))

        Bind(Button.MouseButton1Click:Connect(function()
            if Options.Disabled then return end
            if CloseGearMenus then CloseGearMenus() end

            if ActivePopup then
                ClosePopup()
                return
            end

            Menu.PopupInputBlocker.Visible = true

            local Width = math.max(112, Button.AbsoluteSize.X)
            local VisibleRows = math.min(#Values, 7)
            local RowHeight = 25
            local PopupHeight = math.max(VisibleRows * RowHeight + 10, 35)

            ActivePopup = Create("Frame", {
                Parent = ScreenGui,
                Active = true,
                Position = UDim2.fromOffset(
                    Button.AbsolutePosition.X + Button.AbsoluteSize.X - Width,
                    Button.AbsolutePosition.Y + Button.AbsoluteSize.Y + 5
                ),
                Size = UDim2.fromOffset(Width, PopupHeight),
                BackgroundColor3 = Surface,
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                ZIndex = 100
            })
            Corner(ActivePopup, 0)
            Stroke(ActivePopup, Border, 0, 1)
            Menu:AddSoftGlow(ActivePopup, 100, 6, 0.90, true)

            ActivePopup.Position =
                type(Menu.ClampPopupPosition) == "function"
                and Menu.ClampPopupPosition(ActivePopup, ActivePopup.Position)
                or ActivePopup.Position

            local List = Create("ScrollingFrame", {
                Parent = ActivePopup,
                Position = UDim2.fromOffset(5, 5),
                Size = UDim2.new(1, -10, 1, -10),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.fromOffset(0, #Values * RowHeight),
                ScrollBarThickness = #Values > VisibleRows and 2 or 0,
                ScrollBarImageColor3 = MutedText,
                ScrollBarImageTransparency = 0.48,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                VerticalScrollBarInset = Enum.ScrollBarInset.None,
                ZIndex = 101
            })

            Create("UIListLayout", {
                Parent = List,
                Padding = UDim.new(0, 0),
                SortOrder = Enum.SortOrder.LayoutOrder
            })

            IsOpened = true
            ExpandIndicator:SetOpened(true)
            ButtonStroke.Color = Accent
            Tween(Button, 0.10, {
                BackgroundTransparency = 0.10
            })

            ActivePopupCleanup = function()
                IsOpened = false
                ExpandIndicator:SetOpened(false)
                ButtonStroke.Color = Border
                Tween(Button, 0.10, {
                    BackgroundTransparency = 0.22
                })
            end

            for Index, Value in ipairs(Values) do
                local Selected = Value == Current

                local Option = Create("TextButton", {
                    Parent = List,
                    Size = UDim2.new(1, -2, 0, RowHeight),
                    BackgroundColor3 = SurfaceAlt,
                    BackgroundTransparency = Selected and 0 or 1,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Text = "",
                    LayoutOrder = Index,
                    ZIndex = 102
                })

                local Label = Create("TextLabel", {
                    Parent = Option,
                    Position = UDim2.fromOffset(8, 0),
                    Size = UDim2.new(1, -28, 1, 0),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.BuilderSansMedium,
                    Text = tostring(Value),
                    TextColor3 = Selected and PrimaryText or Color3.fromRGB(137, 149, 155),
                    TextSize = 9,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 103
                })


                Bind(Option.MouseEnter:Connect(function()
                    if not Selected then
                        Tween(Option, 0.08, {
                            BackgroundTransparency = 0.84
                        })
                        Tween(Label, 0.08, {
                            TextColor3 = PrimaryText
                        })
                    end
                end))

                Bind(Option.MouseLeave:Connect(function()
                    if not Selected then
                        Tween(Option, 0.08, {
                            BackgroundTransparency = 1
                        })
                        Tween(Label, 0.08, {
                            TextColor3 = MutedText
                        })
                    end
                end))

                Bind(Option.MouseButton1Click:Connect(function()
                    Set(Value)
                end))
            end
        end))

        RegisterControl(Section, Row, Name)

        return {
            Set = Set,
            Get = function()
                return Current
            end
        }
    end


    local function CreateMultiDropdown(Section, Name, Values, Default, Flag, Options)
        Options = Options or {}
        Values = type(Values) == "table" and Values or {}
        local Row = CreateRow(Section.Body, 22)

        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(0.54, 0, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = Options.Disabled and DisabledText or PrimaryText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 8
        })

        if Options.Gear then
            CreateGear(Row, -124, 13, Name, Flag, {Type = "Dropdown", Values = Values})
        end

        local IsOpened = false
        local Selected = {}
        local OptionStates = {}
        local MaximumSelected = tonumber(Options.Max)
        local AllowEmpty = Options.AllowEmpty ~= false
        local Placeholder = tostring(Options.Placeholder or "None")

        local function ValueKey(Value)
            return typeof(Value) .. ":" .. tostring(Value)
        end

        local function CopySelection()
            local Result = {}
            for _, Value in ipairs(Values) do
                if Selected[ValueKey(Value)] then
                    Result[#Result + 1] = Value
                end
            end
            return Result
        end

        local function CountSelection()
            local Count = 0
            for _ in pairs(Selected) do
                Count = Count + 1
            end
            return Count
        end

        local function BuildSelection(Value)
            local Result = {}
            if type(Value) == "table" then
                local IsArray = #Value > 0
                if IsArray then
                    for _, Item in ipairs(Value) do
                        Result[ValueKey(Item)] = true
                    end
                else
                    for Item, State in pairs(Value) do
                        if State == true then
                            Result[ValueKey(Item)] = true
                        elseif type(Item) == "number" then
                            Result[ValueKey(State)] = true
                        end
                    end
                end
            elseif Value ~= nil then
                Result[ValueKey(Value)] = true
            end

            local Filtered = {}
            local Count = 0
            for _, Item in ipairs(Values) do
                local Key = ValueKey(Item)
                if Result[Key] and (not MaximumSelected or Count < MaximumSelected) then
                    Filtered[Key] = true
                    Count = Count + 1
                end
            end
            if not AllowEmpty and Count == 0 and Values[1] ~= nil then
                Filtered[ValueKey(Values[1])] = true
            end
            return Filtered
        end

        Selected = BuildSelection(Default)
        Menu.Flags[Flag] = CopySelection()

        local Button = Create("TextButton", {
            Parent = Row,
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.fromOffset(140, 18),
            BackgroundColor3 = SurfaceAlt,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 9
        })
        Corner(Button, 0)
        local ButtonStroke = Stroke(Button, Border, 0, 1)

        RegisterAccentTarget(function(NewColor)
            if not ButtonStroke
                or not ButtonStroke.Parent
            then
                return
            end

            ButtonStroke.Color =
                IsOpened
                and NewColor
                or Border
        end)

        local ValueLabel = Create("TextLabel", {
            Parent = Button,
            Position = UDim2.fromOffset(9, 0),
            Size = UDim2.new(1, -30, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = Placeholder,
            TextColor3 = PrimaryText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 10
        })


        local ExpandIndicator =
            Menu.CreateDropdownExpandIndicator(
                Button,
                11
            )

        local function RefreshLabel()
            local Chosen = CopySelection()
            if #Chosen == 0 then
                ValueLabel.Text = Placeholder
                ValueLabel.TextColor3 = MutedText
            else
                local TextValues = {}
                for Index, Value in ipairs(Chosen) do
                    TextValues[Index] = tostring(Value)
                end
                ValueLabel.Text = table.concat(TextValues, ", ")
                ValueLabel.TextColor3 = PrimaryText
            end
        end

        local function RefreshOption(Key)
            local State = OptionStates[Key]
            if not State then return end

            local IsSelected =
                Selected[Key] == true

            State.Selected = IsSelected

            Tween(State.Button, 0.10, {
                BackgroundTransparency =
                    IsSelected and 0.80 or 1,
                BackgroundColor3 =
                    IsSelected
                    and Color3.fromRGB(29, 29, 34)
                    or SurfaceAlt
            })

            Tween(State.Label, 0.10, {
                TextColor3 =
                    IsSelected
                    and PrimaryText
                    or MutedText
            })

            State.Label.Font =
                IsSelected
                and Enum.Font.BuilderSansBold
                or Enum.Font.BuilderSansMedium
        end

        local function Publish()
            local Result = CopySelection()
            Menu.Flags[Flag] = Result
            RefreshLabel()
            if type(Options.Callback) == "function" then
                task.spawn(Options.Callback, Result)
            end
        end

        local function Set(Value)
            Selected = BuildSelection(Value)
            for Key in pairs(OptionStates) do
                RefreshOption(Key)
            end
            Publish()
        end

        local function ToggleValue(Value)
            if Options.Disabled then return end
            local Key = ValueKey(Value)
            if Selected[Key] then
                if not AllowEmpty and CountSelection() <= 1 then return end
                Selected[Key] = nil
            else
                if MaximumSelected and CountSelection() >= MaximumSelected then return end
                Selected[Key] = true
            end
            RefreshOption(Key)
            Publish()
        end

        Menu.Setters[Flag] = Set
        RefreshLabel()

        Bind(Button.MouseEnter:Connect(function()
            Tween(Button, 0.12, {BackgroundColor3 = Color3.fromRGB(29, 29, 34)})
            Tween(ButtonStroke, 0.12, {Color = IsOpened and Accent or Color3.fromRGB(66, 66, 74)})
        end))
        Bind(Button.MouseLeave:Connect(function()
            if not IsOpened then
                Tween(Button, 0.12, {BackgroundColor3 = SurfaceAlt})
                Tween(ButtonStroke, 0.12, {Color = Border})
            end
        end))

        Bind(Button.MouseButton1Click:Connect(function()
            if Options.Disabled then return end
            if CloseGearMenus then CloseGearMenus() end
            if ActivePopup then
                ClosePopup()
                return
            end

            Menu.PopupInputBlocker.Visible = true
            local Width = 128
            local VisibleRows = math.min(#Values, 7)
            local RowHeight = 25
            local PopupHeight = math.max(VisibleRows * RowHeight + 10, 35)
            ActivePopup = Create("Frame", {
                Parent = ScreenGui,
                Active = true,
                Position = UDim2.fromOffset(Button.AbsolutePosition.X + Button.AbsoluteSize.X - Width, Button.AbsolutePosition.Y + Button.AbsoluteSize.Y + 6),
                Size = UDim2.fromOffset(Width, PopupHeight),
                BackgroundColor3 = Surface,
                BackgroundTransparency = 0.035,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                ZIndex = 100
            })
            Corner(ActivePopup, 5)
            Stroke(ActivePopup, Border, 0.46, 1)
            Menu:AddSoftGlow(ActivePopup, 100, 6, 0.90, true)
            ActivePopup.Position = type(Menu.ClampPopupPosition) == "function" and Menu.ClampPopupPosition(ActivePopup, ActivePopup.Position) or ActivePopup.Position

            local List = Create("ScrollingFrame", {
                Parent = ActivePopup,
                Position = UDim2.fromOffset(5, 5),
                Size = UDim2.new(1, -10, 1, -10),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.fromOffset(0, #Values * RowHeight),
                ScrollBarThickness = #Values > VisibleRows and 2 or 0,
                ScrollBarImageColor3 = MutedText,
                ScrollBarImageTransparency = 0.48,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                ZIndex = 101
            })

            Create("UIListLayout", {
                Parent = List,
                Padding = UDim.new(0, 0),
                SortOrder = Enum.SortOrder.LayoutOrder
            })

            IsOpened = true
            ExpandIndicator:SetOpened(true)
            ButtonStroke.Color = Accent
            Tween(Button, 0.12, {BackgroundColor3 = Color3.fromRGB(29, 29, 34)})

            OptionStates = {}
            ActivePopupCleanup = function()
                IsOpened = false
                ExpandIndicator:SetOpened(false)
                OptionStates = {}
                ButtonStroke.Color = Border
                Tween(Button, 0.12, {BackgroundColor3 = SurfaceAlt})
            end

            for _, Value in ipairs(Values) do
                local Key = ValueKey(Value)
                local Option = Create("TextButton", {
                    Parent = List,
                    Size = UDim2.new(1, -2, 0, RowHeight),
                    BackgroundColor3 = SurfaceAlt,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Text = "",
                    ZIndex = 102
                })
                Corner(Option, 5)

                local Label = Create("TextLabel", {
                    Parent = Option,
                    Position = UDim2.fromOffset(9, 0),
                    Size = UDim2.new(1, -18, 1, 0),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.BuilderSansMedium,
                    Text = tostring(Value),
                    TextColor3 = PrimaryText,
                    TextSize = 10,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 103
                })

                OptionStates[Key] = {
                    Button = Option,
                    Label = Label,
                    Selected = false
                }
                RefreshOption(Key)

                Bind(Option.MouseEnter:Connect(function()
                    if not Selected[Key] then
                        Tween(Option, 0.10, {BackgroundTransparency = 0, BackgroundColor3 = Color3.fromRGB(29, 29, 34)})
                    end
                end))
                Bind(Option.MouseLeave:Connect(function()
                    if not Selected[Key] then
                        Tween(Option, 0.10, {BackgroundTransparency = 1, BackgroundColor3 = Surface})
                    end
                end))
                Bind(Option.MouseButton1Click:Connect(function()
                    ToggleValue(Value)
                end))
            end
        end))

        RegisterControl(Section, Row, Name)
        return {
            Set = Set,
            Get = CopySelection,
            Select = function(_, Value)
                if not Selected[ValueKey(Value)] then ToggleValue(Value) end
            end,
            Deselect = function(_, Value)
                if Selected[ValueKey(Value)] then ToggleValue(Value) end
            end,
            Clear = function()
                Set({})
            end
        }
    end

    function CreateFlagSelector(Section, Name, Items, Flag, Options)
        Options = Options or {}
        Items = type(Items) == "table" and Items or {}

        local Bindings = {}
        for Index, Item in ipairs(Items) do
            local Binding = {}
            if type(Item) == "table" then
                Binding.Name = tostring(Item.Name or Item.Label or Item.Value or Item.Flag or ("Item " .. tostring(Index)))
                Binding.Value = Item.Value ~= nil and Item.Value or Binding.Name
                Binding.Flag = tostring(Item.Flag or Binding.Name)
                Binding.Default = Item.Default == true
                Binding.Callback = Item.Callback
            else
                Binding.Name = tostring(Item)
                Binding.Value = Item
                Binding.Flag = Binding.Name
                Binding.Default = false
            end
            Binding.Key = typeof(Binding.Value) .. ":" .. tostring(Binding.Value)
            Bindings[#Bindings + 1] = Binding
        end

        local Row = CreateRow(Section.Body, 28)
        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(0.54, 0, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = Options.Disabled and DisabledText or PrimaryText,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 8
        })

        if Options.Gear then
            local Values = {}
            for Index, Binding in ipairs(Bindings) do Values[Index] = Binding.Value end
            CreateGear(Row, -124, 13, Name, Flag, {Type = "Dropdown", Values = Values})
        end

        local Button = Create("TextButton", {
            Parent = Row,
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.fromOffset(118, 24),
            BackgroundColor3 = SurfaceAlt,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 9
        })
        Corner(Button, 6)
        local ButtonStroke = Stroke(Button, Border, 0.08, 1)

        local ValueLabel = Create("TextLabel", {
            Parent = Button,
            Position = UDim2.fromOffset(9, 0),
            Size = UDim2.new(1, -30, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = tostring(Options.Placeholder or "None"),
            TextColor3 = MutedText,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 10
        })

        local ExpandIndicator = Menu.CreateDropdownExpandIndicator(Button, 11)
        local Selected = {}
        local OptionStates = {}
        local IsOpened = false
        local Updating = false

        local function CopySelection()
            local Result = {}
            for _, Binding in ipairs(Bindings) do
                if Selected[Binding.Key] then Result[#Result + 1] = Binding.Value end
            end
            return Result
        end

        local function RefreshLabel()
            local Chosen = CopySelection()
            if #Chosen == 0 then
                ValueLabel.Text = tostring(Options.Placeholder or "None")
                ValueLabel.TextColor3 = MutedText
            elseif #Chosen == #Bindings and #Bindings > 2 then
                ValueLabel.Text = "All"
                ValueLabel.TextColor3 = PrimaryText
            elseif #Chosen <= 2 then
                local Names = {}
                for Index, Value in ipairs(Chosen) do Names[Index] = tostring(Value) end
                ValueLabel.Text = table.concat(Names, ", ")
                ValueLabel.TextColor3 = PrimaryText
            else
                ValueLabel.Text = tostring(#Chosen) .. " selected"
                ValueLabel.TextColor3 = PrimaryText
            end
        end

        local function RefreshOption(Binding)
            local State = OptionStates[Binding.Key]
            if not State then return end
            local Active = Selected[Binding.Key] == true
            State.Selected = Active
            Tween(State.Button, 0.10, {
                BackgroundTransparency = Active and 0.80 or 1,
                BackgroundColor3 = Active and Color3.fromRGB(29, 29, 34) or SurfaceAlt
            })
            Tween(State.Label, 0.10, {TextColor3 = Active and PrimaryText or MutedText})
            State.Label.Font = Active and Enum.Font.BuilderSansBold or Enum.Font.BuilderSansMedium
            State.Check.BackgroundTransparency = Active and 0 or 1
            State.Check.BackgroundColor3 = Accent
            State.CheckStroke.Color = Active and Accent or Border
            State.CheckStroke.Transparency = Active and 0.04 or 0.18
        end

        local function PublishMaster(FireCallback)
            local Result = CopySelection()
            Menu.Flags[Flag] = Result
            RefreshLabel()
            if FireCallback and type(Options.Callback) == "function" then
                task.spawn(Options.Callback, Result)
            end
        end

        local function ApplyBinding(Binding, Value, FireCallback)
            local State = Value == true
            local Previous = Selected[Binding.Key] == true
            if State then Selected[Binding.Key] = true else Selected[Binding.Key] = nil end
            Menu.Flags[Binding.Flag] = State
            RefreshOption(Binding)
            if FireCallback and Previous ~= State and type(Binding.Callback) == "function" then
                task.spawn(Binding.Callback, State)
            end
        end

        local function Set(Value)
            if Updating then return end
            Updating = true
            local Wanted = {}
            if type(Value) == "table" then
                if #Value > 0 then
                    for _, Item in ipairs(Value) do Wanted[typeof(Item) .. ":" .. tostring(Item)] = true end
                else
                    for Item, State in pairs(Value) do
                        if State == true then Wanted[typeof(Item) .. ":" .. tostring(Item)] = true end
                    end
                end
            elseif Value ~= nil then
                Wanted[typeof(Value) .. ":" .. tostring(Value)] = true
            end
            for _, Binding in ipairs(Bindings) do
                local WantedState = Wanted[Binding.Key] == true
                if Menu.Flags[Binding.Flag] ~= WantedState then
                    ApplyFlagValue(Binding.Flag, WantedState)
                end
                ApplyBinding(Binding, Menu.Flags[Binding.Flag] == true, true)
            end
            Updating = false
            PublishMaster(true)
        end

        local function ToggleBinding(Binding)
            if Options.Disabled then return end
            local NewValue = not (Menu.Flags[Binding.Flag] == true)
            ApplyFlagValue(Binding.Flag, NewValue)
            ApplyBinding(Binding, Menu.Flags[Binding.Flag] == true, true)
            PublishMaster(true)
        end

        for _, Binding in ipairs(Bindings) do
            local Existing = Menu.Flags[Binding.Flag]
            local Initial = type(Existing) == "boolean" and Existing or Binding.Default
            ApplyBinding(Binding, Initial, false)
        end
        PublishMaster(false)

        Menu.Setters[Flag] = Set

        local SelectorController = {
            Flag = Flag,
            ChildFlags = {}
        }
        for _, Binding in ipairs(Bindings) do
            SelectorController.ChildFlags[Binding.Flag] = true
        end
        SelectorController.SyncFromFlags = function()
            if Updating then return end
            Updating = true
            for _, Binding in ipairs(Bindings) do
                local State = Menu.Flags[Binding.Flag] == true
                if State then Selected[Binding.Key] = true else Selected[Binding.Key] = nil end
                RefreshOption(Binding)
            end
            Updating = false
            PublishMaster(false)
        end
        Menu.FlagSelectorControllers[Flag] = SelectorController

        RegisterAccentTarget(function(NewColor)
            if ButtonStroke and ButtonStroke.Parent then ButtonStroke.Color = IsOpened and NewColor or Border end
            for _, State in pairs(OptionStates) do
                if State.Selected then
                    State.Check.BackgroundColor3 = NewColor
                    State.CheckStroke.Color = NewColor
                end
            end
        end)

        Bind(Button.MouseEnter:Connect(function()
            Tween(Button, 0.12, {BackgroundColor3 = Color3.fromRGB(29, 29, 34)})
            Tween(ButtonStroke, 0.12, {Color = IsOpened and Accent or Color3.fromRGB(66, 66, 74)})
        end))

        Bind(Button.MouseLeave:Connect(function()
            if not IsOpened then
                Tween(Button, 0.12, {BackgroundColor3 = SurfaceAlt})
                Tween(ButtonStroke, 0.12, {Color = Border})
            end
        end))

        Bind(Button.MouseButton1Click:Connect(function()
            if Options.Disabled then return end
            if CloseGearMenus then CloseGearMenus() end
            if ActivePopup then
                ClosePopup()
                return
            end

            Menu.PopupInputBlocker.Visible = true
            local Width = math.max(168, tonumber(Options.Width) or 168)
            local VisibleRows = math.min(#Bindings, tonumber(Options.VisibleRows) or 8)
            local RowHeight = 25
            local PopupHeight = math.max(VisibleRows * RowHeight + 10, 35)
            ActivePopup = Create("Frame", {
                Parent = ScreenGui,
                Active = true,
                Position = UDim2.fromOffset(Button.AbsolutePosition.X + Button.AbsoluteSize.X - Width, Button.AbsolutePosition.Y + Button.AbsoluteSize.Y + 6),
                Size = UDim2.fromOffset(Width, PopupHeight),
                BackgroundColor3 = Surface,
                BackgroundTransparency = 0.035,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                ZIndex = 100
            })
            Corner(ActivePopup, 5)
            Stroke(ActivePopup, Border, 0.46, 1)
            Menu:AddSoftGlow(ActivePopup, 100, 6, 0.90, true)
            ActivePopup.Position = type(Menu.ClampPopupPosition) == "function" and Menu.ClampPopupPosition(ActivePopup, ActivePopup.Position) or ActivePopup.Position

            local List = Create("ScrollingFrame", {
                Parent = ActivePopup,
                Position = UDim2.fromOffset(5, 5),
                Size = UDim2.new(1, -10, 1, -10),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.fromOffset(0, #Bindings * RowHeight),
                ScrollBarThickness = #Bindings > VisibleRows and 2 or 0,
                ScrollBarImageColor3 = MutedText,
                ScrollBarImageTransparency = 0.48,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                ZIndex = 101
            })
            Create("UIListLayout", {Parent = List, Padding = UDim.new(0, 0), SortOrder = Enum.SortOrder.LayoutOrder})

            IsOpened = true
            ExpandIndicator:SetOpened(true)
            ButtonStroke.Color = Accent
            Tween(Button, 0.12, {BackgroundColor3 = Color3.fromRGB(29, 29, 34)})
            OptionStates = {}
            ActivePopupCleanup = function()
                IsOpened = false
                ExpandIndicator:SetOpened(false)
                OptionStates = {}
                ButtonStroke.Color = Border
                Tween(Button, 0.12, {BackgroundColor3 = SurfaceAlt})
            end

            for Index, Binding in ipairs(Bindings) do
                local CurrentBinding = Binding
                local Option = Create("TextButton", {
                    Parent = List,
                    Size = UDim2.new(1, -2, 0, RowHeight),
                    BackgroundColor3 = SurfaceAlt,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Text = "",
                    LayoutOrder = Index,
                    ZIndex = 102
                })
                Corner(Option, 5)

                local Label = Create("TextLabel", {
                    Parent = Option,
                    Position = UDim2.fromOffset(9, 0),
                    Size = UDim2.new(1, -38, 1, 0),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.BuilderSansMedium,
                    Text = CurrentBinding.Name,
                    TextColor3 = MutedText,
                    TextSize = 10,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 103
                })

                local CheckBox = Create("Frame", {
                    Parent = Option,
                    AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -9, 0.5, 0),
                    Size = UDim2.fromOffset(12, 12),
                    BackgroundColor3 = Surface,
                    BackgroundTransparency = 0.18,
                    BorderSizePixel = 0,
                    ZIndex = 103
                })
                Corner(CheckBox, 3)
                local CheckStroke = Stroke(CheckBox, Border, 0.18, 1)
                local Check = Create("Frame", {
                    Parent = CheckBox,
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(6, 6),
                    BackgroundColor3 = Accent,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ZIndex = 104
                })
                Corner(Check, 2)

                OptionStates[CurrentBinding.Key] = {
                    Button = Option,
                    Label = Label,
                    Check = Check,
                    CheckStroke = CheckStroke,
                    Selected = false
                }
                RefreshOption(CurrentBinding)

                Bind(Option.MouseEnter:Connect(function()
                    if not Selected[CurrentBinding.Key] then
                        Tween(Option, 0.10, {BackgroundTransparency = 0.84, BackgroundColor3 = Color3.fromRGB(29, 29, 34)})
                    end
                end))
                Bind(Option.MouseLeave:Connect(function()
                    if not Selected[CurrentBinding.Key] then
                        Tween(Option, 0.10, {BackgroundTransparency = 1, BackgroundColor3 = SurfaceAlt})
                    end
                end))
                Bind(Option.MouseButton1Click:Connect(function() ToggleBinding(CurrentBinding) end))
            end
        end))

        RegisterControl(Section, Row, Name)
        return {
            Set = Set,
            Get = CopySelection,
            SetElement = function(_, Value, State)
                local Key = typeof(Value) .. ":" .. tostring(Value)
                for _, Binding in ipairs(Bindings) do
                    if Binding.Key == Key then
                        ApplyFlagValue(Binding.Flag, State == true)
                        ApplyBinding(Binding, Menu.Flags[Binding.Flag] == true, true)
                        PublishMaster(true)
                        break
                    end
                end
            end
        }
    end

