    local function GetKeybindRuntimeKey(Flag, BindData)
        return BindData.Id or (tostring(Flag) .. ":" .. tostring(BindData.Display or BindData.Key or ""))
    end

    local function GatherKeybindEntries()
        local Entries = {}
        local AllBinds = SavedPositions.ControlBinds or {}
        local ControlNames = Menu.BindSystem.ControlNames or {}

        for TargetFlag, Binds in pairs(AllBinds) do
            TargetFlag = tostring(TargetFlag)
            local Name = ControlNames[TargetFlag]

            if type(Name) == "string"
                and type(Binds) == "table"
                and type(Menu.Flags[TargetFlag]) == "boolean" then
                for _, BindData in ipairs(Binds) do
                    if type(BindData) == "table" and BindData.ShowInBinds ~= false then
                        local Display = BindData.Display

                        if type(Display) ~= "string" or Display == "" then
                            Display = Menu.BindSystem.BuildBindDisplay(BindData.Key, BindData.Modifiers)
                            BindData.Display = Display
                        end

                        local RuntimeKey = Menu.BindSystem.GetRuntimeKey(TargetFlag, BindData)
                        local Active = BindData.Mode == "Hold"
                            and Menu.BindRuntime[RuntimeKey] ~= nil
                            or Menu.Flags[TargetFlag] == true

                        Entries[#Entries + 1] = {
                            Name = Name,
                            Key = Display,
                            Active = Active,
                            Enabled = Menu.Flags[TargetFlag] == true,
                            Mode = BindData.Mode == "Hold" and "Hold" or "Toggle"
                        }
                    end
                end
            end
        end

        table.sort(Entries, function(A, B)
            local Left = string.lower(A.Name)
            local Right = string.lower(B.Name)
            if Left == Right then
                return tostring(A.Key) < tostring(B.Key)
            end
            return Left < Right
        end)

        return Entries
    end

    local function BuildKeybindSignature(Entries)
        local Parts = {}
        for Index, Entry in ipairs(Entries) do
            Parts[Index] = table.concat({
                Entry.Name,
                Entry.Key,
                tostring(Entry.Active),
                tostring(Entry.Enabled),
                Entry.Mode
            }, "\31")
        end
        return table.concat(Parts, "\30")
    end

    local function ClearKeybindRows()
        for _, Object in ipairs(KeybindRows:GetChildren()) do
            Object:Destroy()
        end
    end

    local function RefreshKeybindList(Force)
        local Entries = GatherKeybindEntries()
        local Signature = BuildKeybindSignature(Entries)
        if not Force and Signature == KeybindListSignature then
            return
        end
        KeybindListSignature = Signature
        ClearKeybindRows()

        local RowCount = #Entries
        local WindowWidth = 126
        local KeyColumnWidth = 30

        if RowCount == 0 then
            WindowWidth = 126
            Create("TextLabel", {
                Parent = KeybindRows,
                Position = UDim2.fromOffset(0, 0),
                Size = UDim2.new(1, 0, 0, 16),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSans,
                Text = "No hotkeys",
                TextColor3 = MutedText,
                TextSize = 9,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 74
            })
        else
            for _, Entry in ipairs(Entries) do
                local KeyText = "[" .. string.upper(tostring(Entry.Key or "")) .. "]"
                Entry.KeyText = KeyText
                local MeasuredKey = math.ceil(Menu.KeybindListUI.MeasureText(KeyText, 9)) + 3
                KeyColumnWidth = math.max(KeyColumnWidth, MeasuredKey)
            end

            KeyColumnWidth = math.clamp(KeyColumnWidth, 30, 54)

            for _, Entry in ipairs(Entries) do
                local NameWidth = math.ceil(Menu.KeybindListUI.MeasureText(Entry.Name, 10))
                WindowWidth = math.max(WindowWidth, 21 + KeyColumnWidth + 5 + NameWidth + 18)
            end

            WindowWidth = math.clamp(WindowWidth, 126, 214)

            for Index, Entry in ipairs(Entries) do
                local Row = Create("Frame", {
                    Parent = KeybindRows,
                    Position = UDim2.fromOffset(0, (Index - 1) * 19),
                    Size = UDim2.new(1, 0, 0, 18),
                    BackgroundTransparency = 1,
                    ZIndex = 74
                })

                local Switch = Create("Frame", {
                    Parent = Row,
                    Position = UDim2.fromOffset(0, 4),
                    Size = UDim2.fromOffset(16, 9),
                    BackgroundColor3 = Entry.Enabled and Accent or Border,
                    BackgroundTransparency = Entry.Enabled and 0.16 or 0.32,
                    BorderSizePixel = 0,
                    ZIndex = 75
                })
                Corner(Switch, 9)

                local SwitchKnob = Create("Frame", {
                    Parent = Switch,
                    Position = Entry.Enabled and UDim2.fromOffset(8, 1) or UDim2.fromOffset(1, 1),
                    Size = UDim2.fromOffset(7, 7),
                    BackgroundColor3 = PrimaryText,
                    BackgroundTransparency = 0.02,
                    BorderSizePixel = 0,
                    ZIndex = 76
                })
                Corner(SwitchKnob, 7)

                Create("TextLabel", {
                    Parent = Row,
                    Position = UDim2.fromOffset(21, 0),
                    Size = UDim2.fromOffset(KeyColumnWidth, 18),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.BuilderSansMedium,
                    Text = Entry.KeyText,
                    TextColor3 = Accent,
                    TextSize = 9,
                    TextStrokeColor3 = Color3.new(0, 0, 0),
                    TextStrokeTransparency = 0.76,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 76
                })

                Create("TextLabel", {
                    Parent = Row,
                    Position = UDim2.fromOffset(21 + KeyColumnWidth + 5, 0),
                    Size = UDim2.new(1, -(21 + KeyColumnWidth + 5), 0, 18),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.BuilderSansMedium,
                    Text = Entry.Name,
                    TextColor3 = PrimaryText,
                    TextSize = 10,
                    TextStrokeColor3 = Color3.new(0, 0, 0),
                    TextStrokeTransparency = 0.76,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 75
                })
            end
        end

        KeybindListWindow.Size = UDim2.fromOffset(WindowWidth, 33 + math.max(RowCount, 1) * 19)
        KeybindListWindow.Position = Menu.ClampPopupPosition(KeybindListWindow, KeybindListWindow.Position)
    end

    local function SetKeybindListHidden(Value)
        KeybindListHidden = Value and true or false
