            S.PreviewOrder[Key] = tonumber(Menu.Flags["Player ESP " .. Key .. " Order"]) or Index
        end

        local function GetPreviewOrder(Key)
            return tonumber(S.PreviewOrder[Key]) or 999
        end

        local function SavePreviewOrder()
            for Key, Value in pairs(S.PreviewOrder) do
                Menu.Flags["Player ESP " .. Key .. " Order"] = Value
            end
        end

        local function GetPreviewOffset(Key)
            local Value = Menu.Flags[PreviewElementFlags[Key]]
            return typeof(Value) == "Vector2" and Value or Vector2.zero
        end

        local function SetPreviewOffset(Key, Value)
            local Flag = PreviewElementFlags[Key]
            if not Flag then return end
            if typeof(Value) ~= "Vector2" then Value = Vector2.zero end
            Menu.Flags[Flag] = Vector2.new(
                math.floor(Value.X + (Value.X >= 0 and 0.5 or -0.5)),
                math.floor(Value.Y + (Value.Y >= 0 and 0.5 or -0.5))
            )
        end

        local function GetPreviewZone(Key)
            local Zone = Menu.Flags[PreviewZoneFlags[Key]]
            if Zone ~= "Top" and Zone ~= "Bottom" and Zone ~= "Left" and Zone ~= "Right" then
                Zone = PreviewDefaultZones[Key] or "Bottom"
                Menu.Flags[PreviewZoneFlags[Key]] = Zone
            end
            if Key == "HealthBar" or Key == "HealthValue" then
                if Zone ~= "Left" and Zone ~= "Right" then
                    Zone = PreviewDefaultZones[Key]
                    Menu.Flags[PreviewZoneFlags[Key]] = Zone
                end
            end
            return Zone
        end

        local function SetPreviewZone(Key, Zone)
            if not PreviewZoneFlags[Key] then return end
            if Key == "HealthBar" or Key == "HealthValue" then
                Zone = Zone == "Right" and "Right" or "Left"
            elseif Zone ~= "Top" and Zone ~= "Bottom" and Zone ~= "Left" and Zone ~= "Right" then
                Zone = PreviewDefaultZones[Key] or "Bottom"
            end
            Menu.Flags[PreviewZoneFlags[Key]] = Zone
        end

        local function IsPreviewElementEnabled(Key)
            local Flag = PreviewEnabledFlags[Key]
            return Flag and Menu.Flags[Flag] == true
        end

        local function SetElementPosition(Key, Object, Position)
            if not Object or not Object.Parent or typeof(Position) ~= "Vector2" then return end
            local Offset = GetPreviewOffset(Key)
            local FinalPosition = Position + Offset
            Object.Position = UDim2.fromOffset(
                math.floor(FinalPosition.X + 0.5),
                math.floor(FinalPosition.Y + 0.5)
            )
        end

        local function ApplyPreviewElementLayout()
            local Bounds = S.BoxBounds
            if type(Bounds) ~= "table" then return end

            local MinX, MaxX = Bounds.MinX, Bounds.MaxX
            local MinY, MaxY = Bounds.MinY, Bounds.MaxY
            local CenterX = Bounds.CenterX
            local CenterY = MinY + Bounds.Height * 0.5
            local ZoneLists = {Top = {}, Bottom = {}, Left = {}, Right = {}}

            for _, Key in ipairs(PreviewStackOrder) do
                if Key ~= "HealthValue" and IsPreviewElementEnabled(Key) then
                    local Zone = GetPreviewZone(Key)
                    ZoneLists[Zone][#ZoneLists[Zone] + 1] = Key
                end
            end

            for _, List in pairs(ZoneLists) do
                table.sort(List, function(A, B)
                    local AOrder = GetPreviewOrder(A)
                    local BOrder = GetPreviewOrder(B)
                    if AOrder == BOrder then
                        return tostring(A) < tostring(B)
                    end
                    return AOrder < BOrder
                end)
            end

            local HealthBarZone = GetPreviewZone("HealthBar")
            local HealthBarBase = Vector2.new(HealthBarZone == "Right" and MaxX + 5 or MinX - 9, MinY)
            S.HealthBack.AnchorPoint = Vector2.zero
            SetElementPosition("HealthBar", S.HealthBack, HealthBarBase)

            if IsPreviewElementEnabled("HealthValue") then
                local HealthBarOffset = GetPreviewOffset("HealthBar")
                S.HealthText.AnchorPoint = Vector2.new(1, 0.5)
                local HealthValueBase = Vector2.new(
                    HealthBarBase.X + HealthBarOffset.X - 4,
                    MinY + 7
                )
                SetElementPosition("HealthValue", S.HealthText, HealthValueBase)
            end

            local Objects = {
                HealthValue = S.HealthText,
                Name = S.Name,
                Weapon = S.Weapon,
                Distance = S.Distance,
                Level = S.Level,
                Ammo = S.Ammo,
                Forcefield = S.Forcefield,
                Avatar = S.Avatar,
                Flags = S.Flags
            }

            local function GetObjectHeight(Object)
                if not Object then return 18 end
                local ScaleValue = math.max(0.01, tonumber(S.Scale.Scale) or 1)
                local Height = Object.AbsoluteSize.Y / ScaleValue
                if Height < 1 then
                    Height = Object.Size.Y.Offset
                end
                return math.max(16, math.floor(math.max(Height, Object.Size.Y.Offset) + 0.5))
            end

            local function BuildStackHeights(List)
                local Heights = {}
                local Total = 0
                for Index, Key in ipairs(List) do
                    local Height = GetObjectHeight(Objects[Key])
                    Heights[Index] = Height
                    Total += Height
                end
                if #List > 1 then
                    Total += (#List - 1) * 4
                end
                return Heights, Total
            end

            local LocalBodySize = S.Body.AbsoluteSize / math.max(0.01, tonumber(S.Scale.Scale) or 1)
            local ClampedCenterX = math.clamp(CenterX, 54, LocalBodySize.X - 54)

            do
                local Heights = BuildStackHeights(ZoneLists.Top)
                local CurrentY = MinY - 8
                for Index, Key in ipairs(ZoneLists.Top) do
                    local Object = Objects[Key]
                    Object.AnchorPoint = Vector2.new(0.5, 1)
                    SetElementPosition(Key, Object, Vector2.new(ClampedCenterX, math.max(24, CurrentY)))
                    CurrentY -= Heights[Index] + 4
                end
            end

            do
                local Heights = BuildStackHeights(ZoneLists.Bottom)
                local CurrentY = MaxY + 8
                for Index, Key in ipairs(ZoneLists.Bottom) do
                    local Object = Objects[Key]
                    Object.AnchorPoint = Vector2.new(0.5, 0)
                    SetElementPosition(Key, Object, Vector2.new(ClampedCenterX, math.min(LocalBodySize.Y - 24, CurrentY)))
                    CurrentY += Heights[Index] + 4
                end
            end

            do
                local Heights, TotalHeight = BuildStackHeights(ZoneLists.Left)
                local CursorY = CenterY - (TotalHeight * 0.5)
                for Index, Key in ipairs(ZoneLists.Left) do
                    local Object = Objects[Key]
                    local Height = Heights[Index]
                    Object.AnchorPoint = Vector2.new(1, 0.5)
                    local Y = CursorY + (Height * 0.5)
                    local Extra = HealthBarZone == "Left" and 8 or 0
                    local ObjectWidth = math.max(Object.AbsoluteSize.X / math.max(0.01, tonumber(S.Scale.Scale) or 1), Object.Size.X.Offset, 40)
                    local X = math.max(MinX - 10 - Extra, ObjectWidth + 6)
                    SetElementPosition(Key, Object, Vector2.new(X, math.clamp(Y, 14, LocalBodySize.Y - 14)))
                    CursorY += Height + 4
                end
            end

            do
                local Heights = BuildStackHeights(ZoneLists.Right)
                local CursorY = MinY
                for Index, Key in ipairs(ZoneLists.Right) do
                    local Object = Objects[Key]
                    local Height = Heights[Index]
                    Object.AnchorPoint = Vector2.new(0, 0.5)
                    local Y = CursorY + (Height * 0.5)
                    local Extra = HealthBarZone == "Right" and 8 or 0
                    local ObjectWidth = math.max(Object.AbsoluteSize.X / math.max(0.01, tonumber(S.Scale.Scale) or 1), Object.Size.X.Offset, 40)
                    local X = math.min(MaxX + 10 + Extra, LocalBodySize.X - ObjectWidth - 6)
                    SetElementPosition(Key, Object, Vector2.new(X, math.clamp(Y, 14, LocalBodySize.Y - 14)))
                    CursorY += Height + 4
                end
            end
        end


        local function ResetPreviewLayout()
            for Key in pairs(PreviewElementFlags) do
                SetPreviewZone(Key, PreviewDefaultZones[Key])
                SetPreviewOffset(Key, Vector2.zero)
            end
            for Index, Key in ipairs(PreviewStackOrder) do
                S.PreviewOrder[Key] = Index
            end
            SavePreviewOrder()
            ApplyPreviewElementLayout()
        end

