        local function SaveWindowPosition()
            SavedPositions.EspPreviewPosition = EncodePosition(S.Window.Position)
            SavePositions()
        end

        local function ClampWindow(Position)
            local Camera = workspace.CurrentCamera
            local Viewport = Camera and Camera.ViewportSize or Vector2.new(1920, 1080)
            local Size = S.Window.AbsoluteSize
            if Size.X <= 0 or Size.Y <= 0 then
                Size = Vector2.new(824, 522)
            end
            Size *= S.Scale.Scale
            local HalfX = math.floor(Size.X * 0.5)
            local HalfY = math.floor(Size.Y * 0.5)
            local AbsoluteX = (Position.X.Scale * Viewport.X) + Position.X.Offset
            local AbsoluteY = (Position.Y.Scale * Viewport.Y) + Position.Y.Offset
            local X = math.clamp(AbsoluteX, HalfX, math.max(HalfX, Viewport.X - HalfX))
            local Y = math.clamp(AbsoluteY, HalfY, math.max(HalfY, Viewport.Y - HalfY))
            return UDim2.fromOffset(math.floor(X + 0.5), math.floor(Y + 0.5))
        end

        local function PlacePreviewWithSpacing()
            if SavedPreviewPosition then
                S.Window.Position = ClampWindow(S.Window.Position)
                return
            end
            local CameraObject = workspace.CurrentCamera
            local Viewport = CameraObject and CameraObject.ViewportSize or Vector2.new(1920, 1080)
            local ScaleValue = math.max(0.01, tonumber(S.Scale.Scale) or 1)
            local PreviewSize = S.Window.AbsoluteSize
            if PreviewSize.X < 2 or PreviewSize.Y < 2 then PreviewSize = Vector2.new(824, 522) end
            PreviewSize *= ScaleValue
            local MainPosition = Main.AbsolutePosition
            local MainSize = Main.AbsoluteSize
            if MainSize.X < 2 or MainSize.Y < 2 then MainSize = Vector2.new(744, 610) end
            local Gap = 18
            local RightX = MainPosition.X + MainSize.X + Gap + PreviewSize.X * 0.5
            local LeftX = MainPosition.X - Gap - PreviewSize.X * 0.5
            local CenterY = MainPosition.Y + MainSize.Y * 0.5
            local X = RightX
            if RightX + PreviewSize.X * 0.5 > Viewport.X - 8 then X = LeftX end
            if X - PreviewSize.X * 0.5 < 8 then X = Viewport.X - PreviewSize.X * 0.5 - 8 end
            local Y = math.clamp(CenterY, PreviewSize.Y * 0.5 + 8, Viewport.Y - PreviewSize.Y * 0.5 - 8)
            S.Window.Position = ClampWindow(UDim2.fromOffset(math.floor(X + 0.5), math.floor(Y + 0.5)))
        end

        local function ClearModel(Invalidate)
            if Invalidate ~= false then
                S.LoadGeneration += 1
                S.ReloadQueued = not S.Hidden
            end
            if S.Model and S.Model.Parent then
                S.Model:Destroy()
            end
            S.Model = nil
            S.BasePivot = nil
            S.BoundsValid = false
            for _, Child in ipairs(S.World:GetChildren()) do
                Child:Destroy()
            end
        end

        local function SanitizeModel(Model)
            for _, Object in ipairs(Model:GetDescendants()) do
                if Object:IsA("Animator") then
                    Library.Call(function()
                        for _, Track in ipairs(Object:GetPlayingAnimationTracks()) do
                            Track:Stop(0)
                        end
                    end)
                    Object:Destroy()
                elseif Object:IsA("Script") or Object:IsA("LocalScript") or Object:IsA("AnimationController") then
                    Object:Destroy()
                elseif Object:IsA("Motor6D") then
                    Object.Transform = CFrame.identity
                elseif Object:IsA("FaceControls") then
                    Object:Destroy()
                elseif Object:IsA("Bone") then
                    local Head = Object:FindFirstAncestor("Head")
                    if not Head then
                        Object.Transform = CFrame.identity
                    end
                elseif Object:IsA("BasePart") then
                    Object.Anchored = Object.Name == "HumanoidRootPart"
                    Object.LocalTransparencyModifier = 0
                    Object.AssemblyLinearVelocity = Vector3.zero
                    Object.AssemblyAngularVelocity = Vector3.zero
                    Object.CanCollide = false
                    Object.CanTouch = false
                    Object.CanQuery = false
                    Object.CastShadow = false
                elseif Object:IsA("ParticleEmitter") or Object:IsA("Trail") then
                    Object.Enabled = false
                end
            end
            local Humanoid = Model:FindFirstChildWhichIsA("Humanoid")
            if Humanoid then
                Humanoid.AutoRotate = false
                Humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                Humanoid.PlatformStand = false
                Humanoid.Sit = false
                Library.Call(function()
                    Humanoid.EvaluateStateMachine = false
                end)
            end
        end

        local function FreezePreviewPose(Model)
            if not Model or not Model.Parent then return end
            local Humanoid = Model:FindFirstChildWhichIsA("Humanoid")
            if Humanoid then
                Library.Call(function()
                    for _, Track in ipairs(Humanoid:GetPlayingAnimationTracks()) do
                        Track:Stop(0)
                        Track:Destroy()
                    end
                end)
                local Animator = Humanoid:FindFirstChildWhichIsA("Animator")
                if Animator then
                    Library.Call(function()
                        for _, Track in ipairs(Animator:GetPlayingAnimationTracks()) do
                            Track:Stop(0)
                            Track:Destroy()
                        end
                    end)
                    Animator:Destroy()
                end
                Humanoid.AutoRotate = false
                Humanoid.Sit = false
                Humanoid.PlatformStand = false
                Library.Call(function()
                    Humanoid.EvaluateStateMachine = false
                end)
            end
            for _, Object in ipairs(Model:GetDescendants()) do
                if Object:IsA("Animator") or Object:IsA("AnimationController") or Object:IsA("FaceControls") then
                    Object:Destroy()
                elseif Object:IsA("Motor6D") then
                    Object.Transform = CFrame.identity
                elseif Object:IsA("Bone") then
                    local Head = Object:FindFirstAncestor("Head")
                    if not Head then
                        Object.Transform = CFrame.identity
                    end
                elseif Object:IsA("BasePart") then
                    Object.AssemblyLinearVelocity = Vector3.zero
                    Object.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end

