            ["Right Leg"] = true
        }

        local function IsPreviewBodyPart(Object)
            return Object:IsA("BasePart")
                and Object.Transparency < 0.995
                and PreviewBodyNames[Object.Name] == true
        end

        local function StabilizeR6Rig(Model)
            if not Model or not Model.Parent then return end
            local Torso = Model:FindFirstChild("Torso")
            if not Torso or not Torso:IsA("BasePart") then return end

            for _, Joint in ipairs(Torso:GetChildren()) do
                if Joint:IsA("Motor6D") and Joint.Part0 and Joint.Part1 then
                    Joint.Part1.CFrame = Joint.Part0.CFrame * Joint.C0 * Joint.C1:Inverse()
                end
            end

            local Root = Model:FindFirstChild("HumanoidRootPart")
            if Root and Root:IsA("BasePart") then
                local RootJoint = Root:FindFirstChildWhichIsA("Motor6D") or Torso:FindFirstChild("RootJoint")
                if RootJoint and RootJoint.Part0 and RootJoint.Part1 then
                    if RootJoint.Part0 == Root then Root.CFrame = RootJoint.Part1.CFrame * RootJoint.C1 * RootJoint.C0:Inverse()
                    elseif RootJoint.Part1 == Root then Root.CFrame = RootJoint.Part0.CFrame * RootJoint.C0 * RootJoint.C1:Inverse() end
                else
                    Root.CFrame = Torso.CFrame
                end
            end

            for _, Accessory in ipairs(Model:GetChildren()) do
                if Accessory:IsA("Accessory") then
                    local Handle = Accessory:FindFirstChild("Handle")
                    local Weld = Handle and (Handle:FindFirstChild("AccessoryWeld") or Handle:FindFirstChildWhichIsA("Weld"))
                    if Handle and Handle:IsA("BasePart") and Weld and Weld.Part0 and Weld.Part1 then
                        if Weld.Part0 == Handle then Handle.CFrame = Weld.Part1.CFrame * Weld.C1 * Weld.C0:Inverse()
                        elseif Weld.Part1 == Handle then Handle.CFrame = Weld.Part0.CFrame * Weld.C0 * Weld.C1:Inverse() end
                    end
                end
            end
        end

        local function GetPreviewParts(Model)
            local Parts = {}
            for _, Object in ipairs(Model:GetDescendants()) do
                if Object:IsA("BasePart") and Object.Name ~= "HumanoidRootPart" and Object.Transparency < 0.995 then
                    local Accessory = Object:FindFirstAncestorWhichIsA("Accessory")
                    if PreviewBodyNames[Object.Name] or (not Accessory and Object.Parent == Model) then
                        Parts[#Parts + 1] = Object
                    end
                end
            end
            return Parts
        end

        local function GetPartsBounds(Parts)
            local Minimum = Vector3.new(math.huge, math.huge, math.huge)
            local Maximum = Vector3.new(-math.huge, -math.huge, -math.huge)
            local Found = false
            for _, PartObject in ipairs(Parts) do
                local Half = PartObject.Size * 0.5
                local PartCFrame = PartObject.CFrame
                for X = -1, 1, 2 do
                    for Y = -1, 1, 2 do
                        for Z = -1, 1, 2 do
                            local Point = PartCFrame:PointToWorldSpace(Vector3.new(Half.X * X, Half.Y * Y, Half.Z * Z))
                            Minimum = Vector3.new(
                                math.min(Minimum.X, Point.X),
                                math.min(Minimum.Y, Point.Y),
                                math.min(Minimum.Z, Point.Z)
                            )
                            Maximum = Vector3.new(
                                math.max(Maximum.X, Point.X),
                                math.max(Maximum.Y, Point.Y),
                                math.max(Maximum.Z, Point.Z)
                            )
                            Found = true
                        end
                    end
                end
            end
            if not Found then
                return nil, nil
            end
            return (Minimum + Maximum) * 0.5, Maximum - Minimum
        end

        local function ApplyModelRotation()
            if S.Model and S.Model.Parent and S.BasePivot then
                local Position = S.BasePivot.Position
                local Rotation = S.BasePivot - Position
                S.Model:PivotTo(CFrame.new(Position) * CFrame.Angles(0, math.rad(S.Rotation), 0) * Rotation)
            end
        end

        local function FrameModel(Model)
            local Parts = GetPreviewParts(Model)
            local Center, BoxSize = GetPartsBounds(Parts)
            if not Center or not BoxSize then
                local BoxCFrame, FallbackSize = Model:GetBoundingBox()
                Center = BoxCFrame.Position
                BoxSize = FallbackSize
            end

            local Pivot = Model:GetPivot()
            Model:PivotTo(CFrame.new(-Center) * Pivot)

            local FacingPart = Model:FindFirstChild("HumanoidRootPart")
                or Model:FindFirstChild("Torso")
                or Model:FindFirstChild("Head")
            local Facing = FacingPart and FacingPart.CFrame.LookVector or Vector3.new(0, 0, -1)
            local FlatFacing = Vector3.new(Facing.X, 0, Facing.Z)
            if FlatFacing.Magnitude > 0.001 then
                FlatFacing = FlatFacing.Unit
                local CurrentYaw = math.atan2(-FlatFacing.X, -FlatFacing.Z)
                local FrontCorrection = math.pi - CurrentYaw
                Model:PivotTo(CFrame.Angles(0, FrontCorrection, 0) * Model:GetPivot())
            else
                Model:PivotTo(CFrame.Angles(0, math.pi, 0) * Model:GetPivot())
            end

            Parts = GetPreviewParts(Model)
            Center, BoxSize = GetPartsBounds(Parts)
            if Center then
                Model:PivotTo(CFrame.new(-Center) * Model:GetPivot())
            else
                BoxSize = select(2, Model:GetBoundingBox())
            end

            BoxSize = Vector3.new(
                math.max(BoxSize.X, 2),
                math.max(BoxSize.Y, 4),
                math.max(BoxSize.Z, 1)
            )
            local ViewSize = S.Viewport.AbsoluteSize
            local Aspect = ViewSize.Y > 0 and math.max(ViewSize.X / ViewSize.Y, 0.25) or 0.78
            local Vertical = math.rad(S.Camera.FieldOfView)
            local Horizontal = 2 * math.atan(math.tan(Vertical * 0.5) * Aspect)
            local DistanceY = (BoxSize.Y * 0.5) / math.max(math.tan(Vertical * 0.5), 0.01)
            local DistanceX = (BoxSize.X * 0.5) / math.max(math.tan(Horizontal * 0.5), 0.01)
            local Distance = math.max(DistanceX, DistanceY) * 1.18 + BoxSize.Z * 0.55
            local FocusY = BoxSize.Y * 0.015
            S.Camera.CFrame = CFrame.new(Vector3.new(0, FocusY, Distance), Vector3.new(0, FocusY, 0))
            S.BasePivot = Model:GetPivot()
            S.Rotation = S.Mode == "3D" and S.Rotation or 0
            ApplyModelRotation()
            S.BoundsValid = false
        end

        local function CreateDescriptionModel()
            if LocalPlayer then
                local UserId = tonumber(LocalPlayer.UserId) or 0 local Creator = Players.CreateHumanoidModelFromUserIdAsync or Players.CreateHumanoidModelFromUserId

                if UserId > 0 and type(Creator) == "function" then
                    local Model
                    Library.Call(function()
                        Model = Creator(Players, UserId)
                    end)

                    if Model and Model:IsA("Model") then
                        local Description local Humanoid = Model:FindFirstChildWhichIsA("Humanoid")

                        if Humanoid then
                            Library.Call(function()
                                Description = Humanoid:GetAppliedDescription()
                            end)
                        end

                        return Model, Description
                    end
                end
            end

            return CloneCurrentCharacterModel()
        end

        local ProjectModelBounds

        local function TryBuildModel(Generation)
            local Character = LocalPlayer and LocalPlayer.Character
            S.Status.Text = Character and Character.Parent and "LOADING LOCAL PLAYER" or "WAITING FOR CHARACTER"
            S.Status.Visible = true
            local Model, Description = CreateDescriptionModel()
            if Generation ~= S.LoadGeneration or not Model then
                if Model then Model:Destroy() end
                return false
            end
            ClearModel(false)
            Model.Name = "LocalPlayerPreview"
            Model.Parent = S.World
            if Generation ~= S.LoadGeneration or not Model.Parent then
                if Model then Model:Destroy() end
                return false
            end
            StabilizeR6Rig(Model)
            SanitizeModel(Model)
            FreezePreviewPose(Model)
            RunService.Heartbeat:Wait()
            StabilizeR6Rig(Model)
            FreezePreviewPose(Model)
            S.Description = Description
            S.Model = Model
            S.Rotation = 0
            FrameModel(Model)
            task.defer(function()
                if S.Model == Model and Model.Parent then
                    StabilizeR6Rig(Model)
                    FreezePreviewPose(Model)
                    FrameModel(Model)
                    ProjectModelBounds()
                end
            end)
            S.Silhouette.Visible = false
            S.Status.Visible = false
            return true
        end

        local function RequestModel()
            if S.Model and S.Model.Parent then
                return
            end
            if S.Loading then
                S.ReloadQueued = true
                return
            end

            S.Loading = true
            S.ReloadQueued = false
            S.LoadGeneration += 1
            local Generation = S.LoadGeneration
            task.spawn(function()
                RunService.Heartbeat:Wait()
                while S.Window.Parent and Generation == S.LoadGeneration and not S.Hidden do
                    if TryBuildModel(Generation) then
                        S.Loading = false
                        S.ReloadQueued = false
                        return
                    end
                    local Character = LocalPlayer and LocalPlayer.Character
                    local Humanoid = Character and Character:FindFirstChildWhichIsA("Humanoid")
                    if Character and Character.Parent and Humanoid then
                        S.Status.Text = "LOADING PREVIEW"
                        S.Status.Visible = true
                        S.Silhouette.Visible = false
                        task.wait(0.15)
                    else
                        S.Status.Text = "WAITING FOR CHARACTER"
                        S.Status.Visible = true
                        S.Silhouette.Visible = true
                        task.wait(0.25)
                    end
                end

                S.Loading = false
                if S.ReloadQueued and S.Window.Parent and not S.Hidden and not S.Model then
                    S.ReloadQueued = false
                    task.defer(RequestModel)
                end
            end)
        end

        ProjectModelBounds = function()
            if not S.Model or not S.Model.Parent then
                S.BoundsValid = false
                return
            end
            local PixelViewSize = S.Viewport.AbsoluteSize
            if PixelViewSize.X < 2 or PixelViewSize.Y < 2 then
                S.BoundsValid = false
                return
            end
            local UiScale = math.max(0.01, tonumber(S.Scale.Scale) or 1)
            local LocalViewSize = PixelViewSize / UiScale
            local FocalLength = PixelViewSize.Y / (2 * math.tan(math.rad(S.Camera.FieldOfView) * 0.5))
            local MinX, MinY = math.huge, math.huge
            local MaxX, MaxY = -math.huge, -math.huge
            local AnyVisible = false
            local Parts = GetPreviewParts(S.Model)
            for _, PartObject in ipairs(Parts) do
                local PartCFrame = PartObject.CFrame
                local Half = PartObject.Size * 0.5
                for X = -1, 1, 2 do
                    for Y = -1, 1, 2 do
                        for Z = -1, 1, 2 do
                            local WorldPoint = PartCFrame:PointToWorldSpace(Vector3.new(Half.X * X, Half.Y * Y, Half.Z * Z))
                            local CameraPoint = S.Camera.CFrame:PointToObjectSpace(WorldPoint)
                            local Depth = -CameraPoint.Z
                            if Depth > 0.01 then
                                local ScreenX = (PixelViewSize.X * 0.5) + ((CameraPoint.X * FocalLength) / Depth)
                                local ScreenY = (PixelViewSize.Y * 0.5) - ((CameraPoint.Y * FocalLength) / Depth)
                                MinX = math.min(MinX, ScreenX / UiScale)
                                MinY = math.min(MinY, ScreenY / UiScale)
                                MaxX = math.max(MaxX, ScreenX / UiScale)
                                MaxY = math.max(MaxY, ScreenY / UiScale)
                                AnyVisible = true
                            end
                        end
                    end
                end
            end
            if not AnyVisible then
                S.BoundsValid = false
                return
            end
            local PaddingX = 5
            local PaddingY = 4
            local NameGap = 25
            local InfoGap = 26
            local SideGap = 10
            local TopCount, BottomCount, LeftCount, RightCount = 0, 0, 0, 0
            for _, Key in ipairs(PreviewStackOrder) do
                if IsPreviewElementEnabled(Key) then
                    local Zone = GetPreviewZone(Key)
                    if Zone == "Top" then TopCount += 1
                    elseif Zone == "Bottom" then BottomCount += 1
                    elseif Zone == "Left" then LeftCount += 1
                    elseif Zone == "Right" then RightCount += 1 end
                end
            end
            local TopReserve = math.max(44, 18 + TopCount * 22)
            local BottomReserve = math.max(48, 18 + BottomCount * 22)
            local LeftReserve = LeftCount > 0 and 92 or 20
            local RightReserve = RightCount > 0 and 92 or 20
            if GetPreviewZone("HealthBar") == "Left" then LeftReserve = math.max(LeftReserve, 28) end
            if GetPreviewZone("HealthBar") == "Right" then RightReserve = math.max(RightReserve, 28) end
            MinX = math.clamp(MinX - PaddingX, LeftReserve, LocalViewSize.X - RightReserve - 56)
            MinY = math.clamp(MinY - PaddingY, TopReserve, LocalViewSize.Y - BottomReserve - 110)
            MaxX = math.clamp(MaxX + PaddingX, MinX + 56, LocalViewSize.X - RightReserve)
            MaxY = math.clamp(MaxY + PaddingY, MinY + 110, LocalViewSize.Y - BottomReserve)
            local Width = MaxX - MinX
            local Height = MaxY - MinY
            if Width < 56 or Height < 110 then
                S.BoundsValid = false
                return
            end
            local CenterX = MinX + Width * 0.5
            S.Box.Position = UDim2.fromOffset(math.floor(MinX + 0.5), math.floor(MinY + 0.5))
            S.Box.Size = UDim2.fromOffset(math.floor(Width + 0.5), math.floor(Height + 0.5))
            S.HealthBack.Size = UDim2.fromOffset(4, math.floor(Height + 0.5))
            S.Name.Size = UDim2.fromOffset(math.max(90, math.floor(Width + 60)), 20)
            S.Weapon.Size = UDim2.fromOffset(math.max(100, math.floor(Width + 70)), 18)
            S.Distance.Size = UDim2.fromOffset(math.max(70, math.floor(Width + 40)), 18)
            S.Level.Size = UDim2.fromOffset(math.max(70, math.floor(Width + 40)), 18)
            S.Ammo.Size = UDim2.fromOffset(math.max(70, math.floor(Width + 40)), 18)
            S.Forcefield.Size = UDim2.fromOffset(math.max(90, math.floor(Width + 60)), 18)
            S.Avatar.Size = UDim2.fromOffset(30, 30)
            S.Flags.Size = UDim2.fromOffset(math.max(90, math.floor(Width + 60)), 18)

            S.BoxBounds = {
                MinX = MinX,
                MaxX = MaxX,
                MinY = MinY,
                MaxY = MaxY,
                Width = Width,
                Height = Height,
                CenterX = CenterX
            }


            S.BoundsValid = true
            ApplyPreviewElementLayout()
        end

        local function GetFlag(Name, Default)
            local Value = Menu.Flags[Name]
            if Value == nil then
                return Default
            end
            return Value
        end

        local function SetPreviewLine(Line, A, B, Thickness, Color, Visible)
            if not Line then return end
            Visible = Visible == true and typeof(A) == "Vector2" and typeof(B) == "Vector2"
            Line.Visible = Visible
            if not Visible then return end
            local Delta = B - A
            local Length = Delta.Magnitude
            if Length < 0.5 then
                Line.Visible = false
                return
            end
            Line.Position = UDim2.fromOffset((A.X + B.X) * 0.5, (A.Y + B.Y) * 0.5)
            Line.Size = UDim2.fromOffset(Length, math.max(1, tonumber(Thickness) or 1))
            Line.Rotation = math.deg(math.atan2(Delta.Y, Delta.X))
            Line.BackgroundColor3 = Color
        end

        local function UpdatePreviewExtraGeometry(DisplayEnabled, BoxColor)
            local Bounds = S.BoxBounds
            if type(Bounds) ~= "table" or not S.BoundsValid then
                if S.BoxGlow then S.BoxGlow.Visible = false end
                if S.LookLine then S.LookLine.Visible = false end
                if S.TracerLine then S.TracerLine.Visible = false end
                if S.Prediction then S.Prediction.Visible = false end
                if S.Offscreen then S.Offscreen.Visible = false end
                for _, Line in ipairs(S.SkeletonLines or {}) do Line.Visible = false end
                return
            end

            local MinX, MaxX = Bounds.MinX, Bounds.MaxX
            local MinY, MaxY = Bounds.MinY, Bounds.MaxY
            local Width, Height = Bounds.Width, Bounds.Height
            local CenterX = Bounds.CenterX
            local CenterY = MinY + Height * 0.5
            local SkeletonColor = GetFlag("Player ESP Skeleton Color", BoxColor)
            local LookColor = GetFlag("Player ESP Look Color", BoxColor)
            local TracerColor = GetFlag("Player ESP Tracer Color", BoxColor)
            local PredictionColor = GetFlag("Player ESP Prediction Color", BoxColor)
            local OffscreenColor = GetFlag("Player ESP Offscreen Color", BoxColor)
            local GlowColor = GetFlag("Player ESP Box Glow Color", BoxColor)

            local SkeletonEnabled = DisplayEnabled and GetFlag("Player ESP Skeleton", false)
            local Head = Vector2.new(CenterX, MinY + Height * 0.12)
            local Neck = Vector2.new(CenterX, MinY + Height * 0.24)
            local Chest = Vector2.new(CenterX, MinY + Height * 0.39)
            local Pelvis = Vector2.new(CenterX, MinY + Height * 0.57)
            local LShoulder = Vector2.new(CenterX - Width * 0.22, MinY + Height * 0.30)
            local RShoulder = Vector2.new(CenterX + Width * 0.22, MinY + Height * 0.30)
            local LHand = Vector2.new(CenterX - Width * 0.34, MinY + Height * 0.53)
            local RHand = Vector2.new(CenterX + Width * 0.34, MinY + Height * 0.53)
            local LFoot = Vector2.new(CenterX - Width * 0.16, MaxY)
            local RFoot = Vector2.new(CenterX + Width * 0.16, MaxY)
            local Pairs = {
                {Head, Neck}, {Neck, Chest}, {Chest, Pelvis},
                {Neck, LShoulder}, {LShoulder, LHand},
                {Neck, RShoulder}, {RShoulder, RHand},
                {Pelvis, LFoot}, {Pelvis, RFoot}, {LShoulder, RShoulder}
            }
            for Index, Line in ipairs(S.SkeletonLines or {}) do
                local Pair = Pairs[Index]
                SetPreviewLine(Line, Pair and Pair[1], Pair and Pair[2], 1, SkeletonColor, SkeletonEnabled and Pair ~= nil)
            end

            local LookEnabled = DisplayEnabled and GetFlag("Player ESP Look Line", false)
            SetPreviewLine(S.LookLine, Head, Vector2.new(CenterX + Width * 0.58, MinY - Height * 0.03), 1.5, LookColor, LookEnabled)

            local TracerEnabled = DisplayEnabled and GetFlag("Player ESP Tracers", false)
            local ScaleValue = math.max(0.01, tonumber(S.Scale.Scale) or 1)
            local BodySize = S.Body.AbsoluteSize / ScaleValue
            SetPreviewLine(S.TracerLine, Vector2.new(BodySize.X * 0.5, BodySize.Y - 8), Vector2.new(CenterX, MaxY), 1.5, TracerColor, TracerEnabled)

            local PredictionEnabled = DisplayEnabled and GetFlag("Player ESP Prediction", false)
            S.Prediction.Visible = PredictionEnabled
            if PredictionEnabled then
                S.Prediction.Position = UDim2.fromOffset(MaxX + 13, MinY + Height * 0.34)
                S.Prediction.BackgroundColor3 = PredictionColor
            end

            local OffscreenEnabled = DisplayEnabled and GetFlag("Player ESP Offscreen", false)
            S.Offscreen.Visible = OffscreenEnabled
            if OffscreenEnabled then
                S.Offscreen.Position = UDim2.fromOffset(MaxX + 28, CenterY)
                S.Offscreen.TextColor3 = OffscreenColor
            end

            local GlowEnabled = DisplayEnabled and GetFlag("Player ESP Box Glow", false)
            S.BoxGlow.Visible = GlowEnabled
            if GlowEnabled then
                S.BoxGlow.Position = UDim2.fromOffset(MinX - 3, MinY - 3)
                S.BoxGlow.Size = UDim2.fromOffset(Width + 6, Height + 6)
                if S.BoxGlowStroke then
                    S.BoxGlowStroke.Color = GlowColor
                    S.BoxGlowStroke.Transparency = 0.58
                    S.BoxGlowStroke.Thickness = 2
                end
            elseif S.BoxGlowStroke then
                S.BoxGlowStroke.Transparency = 1
            end
        end

        local function UpdateEspStyle()
            local Character = LocalPlayer and LocalPlayer.Character
            local Humanoid = Character and Character:FindFirstChildWhichIsA("Humanoid")
            local Health = math.max(0, math.floor((Humanoid and Humanoid.Health) or 100))
            local MaxHealth = math.max(1, math.floor((Humanoid and Humanoid.MaxHealth) or 100))
            local HealthAlpha = math.clamp(Health / MaxHealth, 0, 1)
            local Enabled = GetFlag("Player ESP", false)
            local DisplayEnabled = Enabled and S.BoundsValid and S.Model and S.Model.Parent ~= nil
            local Boxes = DisplayEnabled and GetFlag("Player ESP Boxes", false)
            local BoxStyle = GetFlag("Player ESP Box Style", "Corners")
            local RawBoxColor = GetFlag("Player ESP Box Color", Accent)
            local AdaptiveEnabled = DisplayEnabled and GetFlag("Player ESP Adaptive Color", false)
            local BoxColor = AdaptiveEnabled and GetFlag("Player ESP Adaptive Visible Color", RawBoxColor) or RawBoxColor
            local FillEnabled = DisplayEnabled and GetFlag("Player ESP Fill", false)
            local FillColor = GetFlag("Player ESP Fill Color", BoxColor)
            local FillTransparency = math.clamp(tonumber(GetFlag("Player ESP Fill Transparency", 0.78)) or 0.78, 0, 1)
            local TextColor = GetFlag("Player ESP Text Color", PrimaryText)
            local HighColor = GetFlag("Player ESP Health High Color", Color3.fromRGB(98, 236, 151))
            local MidColor = GetFlag("Player ESP Health Mid Color", Color3.fromRGB(243, 184, 92))
            local LowColor = GetFlag("Player ESP Health Low Color", Color3.fromRGB(255, 89, 104))
            local HealthColor
            if HealthAlpha < 0.5 then
                HealthColor = LowColor:Lerp(MidColor, HealthAlpha * 2)
            else
                HealthColor = MidColor:Lerp(HighColor, (HealthAlpha - 0.5) * 2)
            end
            local TextSize = math.clamp(tonumber(GetFlag("Player ESP Text Size", 12)) or 12, 10, 20)

            S.Box.Visible = Boxes or FillEnabled
            S.Box.BackgroundColor3 = FillColor
            S.Box.BackgroundTransparency = FillEnabled and FillTransparency or 1
            S.BoxStroke.Transparency = Boxes and BoxStyle == "Full" and 0.04 or 1
            S.BoxStroke.Color = BoxColor
            for _, CornerObject in ipairs(S.Corners) do
                CornerObject.Visible = Boxes and BoxStyle ~= "Full"
                CornerObject.BackgroundColor3 = BoxColor
            end

            local HealthBarEnabled = DisplayEnabled and GetFlag("Player ESP Health Bar", false)
            S.HealthBack.Visible = HealthBarEnabled
            S.HealthDelayed.Visible = HealthBarEnabled and GetFlag("Player ESP Delayed Health", false)
            S.HealthDelayed.Size = UDim2.fromScale(1, math.max(HealthAlpha, 0.82))
            S.HealthDelayed.BackgroundColor3 = GetFlag("Player ESP Delayed Health Color", Color3.fromRGB(255, 184, 92))
            S.HealthFill.Size = UDim2.fromScale(1, HealthAlpha)
            S.HealthFill.BackgroundColor3 = HealthColor
            S.HealthText.Visible = DisplayEnabled and GetFlag("Player ESP Health Value", false)
            S.HealthText.Text = tostring(Health)
            S.HealthText.TextColor3 = HealthColor
            S.HealthText.TextSize = math.max(9, TextSize - 2)

            S.Name.Visible = DisplayEnabled and GetFlag("Player ESP Names", false)
            S.Name.Text = string.upper(LocalPlayer and LocalPlayer.Name or "PLAYER")
            S.Name.TextColor3 = TextColor
            S.Name.TextSize = TextSize

            local Tool = Character and Character:FindFirstChildOfClass("Tool")
            S.Weapon.Visible = DisplayEnabled and GetFlag("Player ESP Weapon", false)
            S.Weapon.Text = Tool and string.upper(Tool.Name) or "NONE"
            S.Weapon.TextColor3 = TextColor
            S.Weapon.TextSize = math.max(9, TextSize - 1)

            S.Distance.Visible = DisplayEnabled and GetFlag("Player ESP Distance", false)
            S.Distance.Text = "0m"
            S.Distance.TextColor3 = TextColor
            S.Distance.TextSize = math.max(9, TextSize - 2)

            S.Level.Visible = DisplayEnabled and GetFlag("Player ESP Level", false)
            S.Level.Text = "Level 55"
            S.Level.TextColor3 = GetFlag("Player ESP Level Color", TextColor)
            S.Level.TextSize = math.max(9, TextSize - 2)

            S.Ammo.Visible = DisplayEnabled and GetFlag("Player ESP Ammo", false)
            S.Ammo.Text = "16/42"
            S.Ammo.TextColor3 = GetFlag("Player ESP Ammo Color", TextColor)
            S.Ammo.TextSize = math.max(9, TextSize - 2)

            S.Forcefield.Visible = DisplayEnabled and GetFlag("Player ESP Forcefield", false)
            S.Forcefield.Text = "[Protected]"
            S.Forcefield.TextColor3 = GetFlag("Player ESP Forcefield Color", Accent)
            S.Forcefield.TextSize = math.max(9, TextSize - 2)

            S.Avatar.Visible = DisplayEnabled and GetFlag("Player ESP Profile Picture", false)
            if S.Avatar.Visible and LocalPlayer then
                S.Avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer.UserId) .. "&w=100&h=100"
            end

            S.Flags.Visible = DisplayEnabled and GetFlag("Player ESP Flags", false)
            S.Flags.Text = "Flagged"
            S.Flags.TextColor3 = GetFlag("Player ESP Flags Color", TextColor)
            S.Flags.TextSize = math.max(9, TextSize - 2)

            UpdatePreviewExtraGeometry(DisplayEnabled, BoxColor)
            UpdateSelectedElements()
            S.Silhouette.Visible = false
            S.Viewport.Ambient = S.Mode == "2D" and Color3.fromRGB(165, 181, 190) or Color3.fromRGB(139, 157, 168)
            S.Viewport.LightDirection = S.Mode == "2D" and Vector3.new(-0.8, -0.4, -1) or Vector3.new(-1, -0.75, -1)
        end

        local function RefreshMode()
            local Is2D = S.Mode == "2D"
            S.ModeHighlight.Position = UDim2.fromOffset(Is2D and 2 or 66, 2)
            S.TwoDButton.TextColor3 = Is2D and Background or MutedText
            S.ThreeDButton.TextColor3 = Is2D and MutedText or Background
            if Is2D then
                S.Rotation = 0
            end
            if S.Model and S.BasePivot then
                ApplyModelRotation()
            elseif S.Window.Visible then
                RequestModel()
            end
        end

        local function RefreshVisibility()
            local Visible =
                S.RequestedVisible == true
                and S.Hidden ~= true

            S.Window.Visible = Visible

            if S.Glow then
                S.Glow.Visible = Visible
            end

            if Visible and not S.Model then
                RequestModel()
            end
        end

