        BindPreviewElementDrag("Avatar", S.Avatar)
        BindPreviewElementDrag("Flags", S.Flags)

        local function BeginModelRotation(Input)
            if Input.UserInputType ~= Enum.UserInputType.MouseButton1
                or S.Mode ~= "3D"
                or not S.Window.Visible
                or S.RotatingModel
                or S.ElementDragging
            then
                return
            end
            local Position = Input.Position
            local BodyPosition = S.Body.AbsolutePosition
            local BodySize = S.Body.AbsoluteSize
            if Position.X < BodyPosition.X or Position.X > BodyPosition.X + BodySize.X
                or Position.Y < BodyPosition.Y or Position.Y > BodyPosition.Y + BodySize.Y then
                return
            end
            S.RotatingModel = true
            S.RotateStart = Position
            S.StartRotation = S.Rotation
        end

        Bind(S.Body.InputBegan:Connect(BeginModelRotation))
        Bind(UserInputService.InputBegan:Connect(BeginModelRotation))

        Bind(S.Header.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                S.Dragging = true
                S.DragStart = Input.Position
                S.StartPosition = S.Window.Position
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if S.ElementDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                local Current = Vector2.new(Input.Position.X, Input.Position.Y)
                local Delta = (Current - S.ElementDragStart) / math.max(0.01, tonumber(S.Scale.Scale) or 1)
                if S.ElementDragging == "HealthBar" then Delta = Vector2.new(Delta.X, 0) end
                local NextOffset = S.ElementDragOffset + Delta
                NextOffset = Vector2.new(
                    math.clamp(NextOffset.X, -180, 180),
                    math.clamp(NextOffset.Y, -160, 160)
                )
                SetPreviewOffset(S.ElementDragging, NextOffset)
                ApplyPreviewElementLayout()
            elseif S.Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                local Delta = Input.Position - S.DragStart
                S.Window.Position = ClampWindow(UDim2.new(
                    S.StartPosition.X.Scale,
                    S.StartPosition.X.Offset + Delta.X,
                    S.StartPosition.Y.Scale,
                    S.StartPosition.Y.Offset + Delta.Y
                ))
            elseif S.RotatingModel and Input.UserInputType == Enum.UserInputType.MouseMovement and S.Mode == "3D" then
                local Delta = Input.Position - S.RotateStart
                S.Rotation = (S.StartRotation + (Delta.X * 0.45)) % 360
                ApplyModelRotation()
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 and S.Dragging then
                S.Dragging = false
                SaveWindowPosition()
            end
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                S.ElementDragging = nil
                S.ElementDragStart = nil
                S.ElementDragOffset = nil
                S.RotatingModel = false
            end
        end))

        if LocalPlayer then
            Bind(LocalPlayer.CharacterAdded:Connect(function()
                task.delay(0.1, function()
                    ClearModel()
                    if not S.Hidden then
                        RequestModel()
                    end
                end)
            end))
            Bind(LocalPlayer.CharacterAppearanceLoaded:Connect(function()
                task.delay(0.2, function()
                    ClearModel()
                    if not S.Hidden then
                        RequestModel()
                    end
                end)
            end))
        end

        local LastUpdate = 0
        Bind(RunService.RenderStepped:Connect(function(DeltaTime)
            if not S.Window.Visible then
                return
            end
            if S.Model and S.Model.Parent then
                FreezePreviewPose(S.Model)
            end
            if S.Model and S.Model.Parent and S.BasePivot and S.Mode ~= "3D" and S.Rotation ~= 0 then
                S.Rotation = 0
                ApplyModelRotation()
            end
            if os.clock() - LastUpdate >= 0.08 then
                LastUpdate = os.clock()
                UpdateEspStyle()
                if S.Model and S.Model.Parent then
                    ProjectModelBounds()
                elseif os.clock() - S.LastRetry > 1.5 then
                    S.LastRetry = os.clock()
                    RequestModel()
                end
            end
        end))

        RegisterAccentTarget(function(NewColor)
            S.ModeHighlight.BackgroundColor3 = NewColor
            if S.Glow then
                S.Glow.ImageColor3 = NewColor
            end
            UpdateEditorElementButtons()
        end)

        Menu.EspPreviewWindow = S.Window
        S.Window.Position = ClampWindow(S.Window.Position)
        task.defer(function()
            if S.Window and S.Window.Parent then PlacePreviewWithSpacing() end
        end)
        SyncPreviewStateFromFlags()
        RefreshMode()
        UpdateEditorElementButtons()
        UpdateEspStyle()
        RefreshVisibility()
    end

    CreateEspPreviewWindow()
    end

