    Menu.BindSystem.CaptureIdentity = function(
        KeyType,
        KeyName
    )
        if not PendingBindCapture then
            return false
        end

        KeyType,
            KeyName =
            Menu.BindSystem.
                CanonicalBindKey(
                    KeyType,
                    KeyName
                )

        if not KeyType
            or not KeyName
            or KeyName == ""
        then
            return false
        end

        if KeyType == "UserInputType"
            and KeyName == "MouseButton1"
        then
            if PendingBindCapture.SetText then
                PendingBindCapture.SetText(
                    "LMB unavailable"
                )
            end

            return true
        end

        local Meta =
            PendingBindCapture.Meta

        local TargetFlag =
            Meta
            and tostring(
                Meta.Flag or ""
            )
            or ""

        if TargetFlag == ""
            or type(
                Menu.Flags[TargetFlag]
            ) ~= "boolean"
        then
            if PendingBindCapture.SetText then
                PendingBindCapture.SetText(
                    "Boolean only"
                )
            end

            PendingBindCapture = nil
            return true
        end

        local Mode =
            PendingBindCapture.Mode
            and PendingBindCapture.Mode()
            or "Toggle"

        Mode =
            Mode == "Hold"
            and "Hold"
            or "Toggle"

        local Modifiers =
            Menu.BindSystem.
                ReadModifiers()

        local Binds =
            Menu.BindSystem.
                GetControlBinds(
                    TargetFlag
                )

        local ShowInBinds =
            PendingBindCapture.ShowInBinds == nil
            or PendingBindCapture.
                ShowInBinds()

        local MetaGateFlag =
            Meta.Info
            and Meta.Info.GateFlag

        local GateFlag =
            Mode == "Hold"
            and type(MetaGateFlag)
                == "string"
            and MetaGateFlag
            or nil

        for Index = #Binds, 1, -1 do
            local Existing =
                Binds[Index]

            local ExistingModifiers =
                type(
                    Existing.Modifiers
                ) == "table"
                and Existing.Modifiers
                or {}

            if Existing.KeyType
                    == KeyType
                and Existing.Key
                    == KeyName
                and (
                    ExistingModifiers.Ctrl
                        == true
                ) == (
                    Modifiers.Ctrl
                        == true
                )
                and (
                    ExistingModifiers.Shift
                        == true
                ) == (
                    Modifiers.Shift
                        == true
                )
                and (
                    ExistingModifiers.Alt
                        == true
                ) == (
                    Modifiers.Alt
                        == true
                )
            then
                table.remove(
                    Binds,
                    Index
                )
            end
        end

        local BindData = {
            Id =
                tostring(
                    os.clock()
                )
                .. tostring(
                    math.random(
                        1000,
                        9999
                    )
                ),
            KeyType = KeyType,
            Key = KeyName,
            Modifiers = Modifiers,
            Display =
                Menu.BindSystem.
                    BuildBindDisplay(
                        KeyName,
                        Modifiers
                    ),
            Mode = Mode,
            ShowInBinds =
                ShowInBinds,
            GateFlag =
                GateFlag
        }

        Binds[#Binds + 1] =
            BindData

        if Menu.KeybindListController
            and Menu.KeybindListController.MarkDirty
        then
            Menu.KeybindListController.
                MarkDirty()
        end

        if PendingBindCapture.SetText then
            PendingBindCapture.SetText(
                BindData.Display
            )
        end

        PendingBindCapture = nil
        return true
    end

    Menu.BindSystem.CaptureInput = function(Input)
        if not PendingBindCapture then
            return false
        end

        if Input.UserInputType
            == Enum.UserInputType.MouseButton1
        then
            return Menu.BindSystem.
                CaptureIdentity(
                    "UserInputType",
                    "MouseButton1"
                )
        end

        if Input.UserInputType
                == Enum.UserInputType.Keyboard
            and Menu.BindSystem.
                IsModifierKey(
                    Input.KeyCode
                )
        then
            return true
        end

        local KeyType,
            KeyName =
            Menu.BindSystem.
                GetInputIdentity(
                    Input
                )

        if not KeyType
            or not KeyName
        then
            return false
        end

        return Menu.BindSystem.
            CaptureIdentity(
                KeyType,
                KeyName
            )
    end

    Menu.BindSystem.ExecutePressed = function(TargetFlag, BindData)
        TargetFlag = tostring(TargetFlag or "Unknown")
        local Current = Menu.Flags[TargetFlag]

        if type(Current) ~= "boolean" or type(BindData) ~= "table" then
            return
        end

        if BindData.Mode ~= "Hold" then
            Menu.BindSystem.ApplyFlagValue(TargetFlag, not Current)
            return
        end

        local GateFlag = type(BindData.GateFlag) == "string" and BindData.GateFlag or nil
        if GateFlag and Menu.Flags[GateFlag] ~= true then
            return
        end

        local RuntimeKey = Menu.BindSystem.GetRuntimeKey(TargetFlag, BindData)
        if Menu.BindRuntime[RuntimeKey] ~= nil then
            return
        end

        local HoldState = Menu.BindHoldState[TargetFlag]
        if type(HoldState) ~= "table" then
            HoldState = {Count = 0, Base = Current == true}
            Menu.BindHoldState[TargetFlag] = HoldState
        end

        HoldState.Count += 1
        Menu.BindRuntime[RuntimeKey] = {
            TargetFlag = TargetFlag,
            GateFlag = GateFlag
        }

        if Current ~= true then
            Menu.BindSystem.ApplyFlagValue(TargetFlag, true)
        end

        if Menu.KeybindListController and Menu.KeybindListController.MarkDirty then
            Menu.KeybindListController.MarkDirty()
        end
    end

    Menu.BindSystem.ProcessIdentityBegan =
        function(
            KeyType,
            KeyName
        )
            local Matched = false
            local ExecutedTargets = {}
            local AllBinds =
                SavedPositions.ControlBinds
                or {}

            for TargetFlag, Binds in pairs(
                AllBinds
            ) do
                TargetFlag =
                    tostring(
                        TargetFlag
                    )

                if type(Binds)
                        == "table"
                    and type(
                        Menu.Flags[
                            TargetFlag
                        ]
                    ) == "boolean"
                    and not ExecutedTargets[
                        TargetFlag
                    ]
                then
                    for _, BindData in ipairs(
                        Binds
                    ) do
                        if Menu.BindSystem.
                            BindMatchesIdentity(
                                BindData,
                                KeyType,
                                KeyName,
                                true
                            )
                        then
                            ExecutedTargets[
                                TargetFlag
                            ] = true

                            Matched = true

                            Menu.BindSystem.
                                ExecutePressed(
                                    TargetFlag,
                                    BindData
                                )

                            break
                        end
                    end
                end
            end

            return Matched
        end

    Menu.BindSystem.ProcessIdentityEnded =
        function(
            KeyType,
            KeyName
        )
            local AllBinds =
                SavedPositions.ControlBinds
                or {}

            for TargetFlag, Binds in pairs(
                AllBinds
            ) do
                TargetFlag =
                    tostring(
                        TargetFlag
                    )

                if type(Binds)
                    == "table"
                then
                    for _, BindData in ipairs(
                        Binds
                    ) do
                        if BindData.Mode
                                == "Hold"
                            and Menu.BindSystem.
                                BindMatchesIdentity(
                                    BindData,
                                    KeyType,
                                    KeyName,
                                    false
                                )
                        then
                            Menu.BindSystem.
                                ReleaseHold(
                                    Menu.BindSystem.
                                        GetRuntimeKey(
                                            TargetFlag,
                                            BindData
                                        )
                                )
                        end
                    end
                end
            end
        end

    Menu.BindSystem.ProcessBegan = function(Input)
        local Matched = false
        local ExecutedTargets = {}
        local AllBinds = SavedPositions.ControlBinds or {}

        for TargetFlag, Binds in pairs(AllBinds) do
            TargetFlag = tostring(TargetFlag)

            if type(Binds) == "table"
                and type(Menu.Flags[TargetFlag]) == "boolean"
                and not ExecutedTargets[TargetFlag] then
                for _, BindData in ipairs(Binds) do
                    if Menu.BindSystem.BindMatchesInput(BindData, Input, true) then
                        ExecutedTargets[TargetFlag] = true
                        Matched = true
                        Menu.BindSystem.ExecutePressed(TargetFlag, BindData)
                        break
                    end
                end
            end
        end

        return Matched
    end

    Menu.BindSystem.ProcessEnded = function(Input)
        local AllBinds = SavedPositions.ControlBinds or {}

        for TargetFlag, Binds in pairs(AllBinds) do
            TargetFlag = tostring(TargetFlag)

            if type(Binds) == "table" then
                for _, BindData in ipairs(Binds) do
                    if BindData.Mode == "Hold"
                        and Menu.BindSystem.BindMatchesInput(BindData, Input, false) then
                        Menu.BindSystem.ReleaseHold(Menu.BindSystem.GetRuntimeKey(TargetFlag, BindData))
                    end
                end
            end
        end
    end

    Bind(UserInputService.InputBegan:Connect(function(Input, Processed)
        if PendingBindCapture then
            if Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode == Enum.KeyCode.Escape then
                if PendingBindCapture.SetText then
                    PendingBindCapture.SetText("Press key")
                end
                PendingBindCapture = nil
                return
            end
            if Menu.BindSystem.CaptureInput(Input) then
                return
            end
        end

        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            local Position = Input.Position
            local function IsInside(Object)
                if not Object or not Object.Parent then
                    return false
                end
                local ObjectPosition = Object.AbsolutePosition
                local ObjectSize = Object.AbsoluteSize
                return Position.X >= ObjectPosition.X and Position.X <= ObjectPosition.X + ObjectSize.X
                    and Position.Y >= ObjectPosition.Y and Position.Y <= ObjectPosition.Y + ObjectSize.Y
            end

            if ActiveGearMenu
                and not IsInside(ActiveGearMenu)
                and not IsInside(ActiveGearBindMenu)
                and not IsInside(ActiveGearHotkeysMenu)
                and not IsInside(ActiveGearButton) then
                CloseGearMenus()
            end

            if ActivePopup and not IsInside(ActivePopup) then
                ClosePopup()
            end
        end

        if Input.UserInputType == Enum.UserInputType.MouseButton1 and PickerOpen and Menu.SettingsUI.ColorPickerContainer.Visible then
            local Position = Input.Position
            local PickerPosition = Menu.SettingsUI.ColorPickerContainer.AbsolutePosition
            local PickerSize = Menu.SettingsUI.ColorPickerContainer.AbsoluteSize
            local PickerAnchor = Menu.SettingsUI.PickerAnchor or Menu.SettingsUI.AccentPreviewButton
            local SwatchPosition = PickerAnchor.AbsolutePosition
            local SwatchSize = PickerAnchor.AbsoluteSize
            local InsidePicker = Position.X >= PickerPosition.X and Position.X <= PickerPosition.X + PickerSize.X
                and Position.Y >= PickerPosition.Y and Position.Y <= PickerPosition.Y + PickerSize.Y
            local InsideSwatch = Position.X >= SwatchPosition.X and Position.X <= SwatchPosition.X + SwatchSize.X
                and Position.Y >= SwatchPosition.Y and Position.Y <= SwatchPosition.Y + SwatchSize.Y
            if not InsidePicker and not InsideSwatch and CanDismissPicker() then
                SetPickerOpen(false)
            end
        end

        local FocusedTextBox = UserInputService:GetFocusedTextBox()

        if not FocusedTextBox and Menu.QuickPanelBindCapture then
            if Input.UserInputType == Enum.UserInputType.Keyboard
                and Input.KeyCode == Enum.KeyCode.Escape
            then
                Menu.QuickPanelBindCapture = false

                if Menu.SettingsUI.QuickPanelBindControl
                    and Menu.SettingsUI.QuickPanelBindControl.Set
                then
                    Menu.SettingsUI.QuickPanelBindControl.Set(
                        Menu.Flags["Quick Panel Bind"]
                    )
                end

                return
            end

            local KeyType, KeyName =
                Menu.BindSystem.GetInputIdentity(Input)

            if KeyType and KeyName then
                KeyType,
                    KeyName =
                    Menu.BindSystem.CanonicalBindKey(
                        KeyType,
                        KeyName
                    )

                local NewBind = {
                    KeyType = KeyType,
                    Key = KeyName,
                    Modifiers = Menu.BindSystem.ReadModifiers()
                }

                if Menu.SettingsUI.QuickPanelBindControl
                    and Menu.SettingsUI.QuickPanelBindControl.Set
                then
                    Menu.SettingsUI.QuickPanelBindControl.Set(NewBind)
                else
                    Menu.Flags["Quick Panel Bind"] = NewBind
                    Menu.QuickPanelBindCapture = false
                end

                return
            end
        end

        local QuickBind =
            Menu.Flags["Quick Panel Bind"]

        if not FocusedTextBox
            and type(QuickBind) == "table"
            and Menu.BindSystem.BindMatchesInput(
                QuickBind,
                Input,
                true
            )
        then
            if Menu.QuickPanelController
                and Menu.QuickPanelController.Toggle
            then
                Menu.QuickPanelController.Toggle()
            end

            return
        end

        local BindMatched = false
        if not FocusedTextBox then
            BindMatched = Menu.BindSystem.ProcessBegan(Input)
        end

        if Processed and not BindMatched then
            return
        end
    end))

    Bind(UserInputService.InputEnded:Connect(function(Input)
        Menu.BindSystem.ProcessEnded(Input)
    end))

    Menu.CustomMouseAccumulator = 0

    Bind(RunService.Heartbeat:Connect(function(DeltaTime)
        Menu.CustomMouseAccumulator +=
            math.clamp(
                DeltaTime,
                0,
                0.05
            )

        if Menu.CustomMouseAccumulator
            < 1 / 30
        then
            return
        end

        Menu.CustomMouseAccumulator = 0

        local States =
            Menu.BindSystem.
                GetCustomMouseStates()

        for _, KeyName in ipairs({
            "MouseButton4",
            "MouseButton5"
        }) do
            local IsDown =
                States[KeyName]
                == true

            local WasDown =
                Menu.BindSystem.
                    CustomMouse.
                    Previous[
                        KeyName
                    ] == true

            if IsDown ~= WasDown then
                Menu.BindSystem.
                    CustomMouse.
                    Previous[
                        KeyName
                    ] = IsDown

                if IsDown then
                    local FocusedTextBox =
                        UserInputService:
                            GetFocusedTextBox()

                    if not FocusedTextBox then
                        if PendingBindCapture then
                            Menu.BindSystem.
                                CaptureIdentity(
                                    "UserInputType",
                                    KeyName
                                )
                        elseif Menu.QuickPanelBindCapture then
                            local NewBind = {
                                KeyType =
                                    "UserInputType",
                                Key = KeyName,
                                Modifiers =
                                    Menu.BindSystem.
                                        ReadModifiers()
                            }

                            if Menu.SettingsUI.
                                QuickPanelBindControl
                                and Menu.SettingsUI.
                                    QuickPanelBindControl.Set
                            then
                                Menu.SettingsUI.
                                    QuickPanelBindControl.Set(
                                        NewBind
                                    )
                            else
                                Menu.Flags[
                                    "Quick Panel Bind"
                                ] = NewBind

                                Menu.QuickPanelBindCapture =
                                    false
                            end
                        else
                            local QuickBind =
                                Menu.Flags[
                                    "Quick Panel Bind"
                                ]

                            if type(QuickBind)
                                    == "table"
                                and Menu.BindSystem.
                                    BindMatchesIdentity(
                                        QuickBind,
                                        "UserInputType",
                                        KeyName,
                                        true
                                    )
                            then
                                if Menu.QuickPanelController
                                    and Menu.QuickPanelController.Toggle
                                then
                                    Menu.QuickPanelController.Toggle()
                                end
                            else
                                Menu.BindSystem.
                                    ProcessIdentityBegan(
                                        "UserInputType",
                                        KeyName
                                    )
                            end
                        end
                    end
                else
                    Menu.BindSystem.
                        ProcessIdentityEnded(
                            "UserInputType",
                            KeyName
                        )
                end
            end
        end
    end))

    Menu.Visible = false
    Main.Visible = false
    Overlay.Visible = false
    InputBlocker.Visible = false
    Menu.SettingsInputBlocker.Visible = false
    Menu.PopupInputBlocker.Visible = false
    Menu.PickerInputBlocker.Visible = false

