        local function NormalizeStatus(Status)
            Status = tostring(Status or "None")
            if Status == "Priority"
                or Status == "Whitelist"
                or Status == "Enemy"
            then
                return Status
            end
            return "None"
        end

        local function GetStatus(Player)
            if not Player then
                return "None"
            end

            if Player == LocalPlayer then
                return "Client"
            end

            return NormalizeStatus(
                Menu.PlayerStatuses[
                    tonumber(Player.UserId) or 0
                ]
            )
        end

        local function CloseStatusDropdown()
            State.DropdownOpen = false
            StatusDropdown.Visible = false
            StatusExpandIndicator:SetOpened(false)
            ActionHolder.Position = UDim2.fromOffset(0, 215)
        end

        local RefreshRows
        local RefreshSelected
        local FriendCache = {}
        local FriendPending = {}

        local function QueueFriendCheck(Player)
            if not Player or Player == LocalPlayer then
                return
            end

            local UserId = tonumber(Player.UserId) or 0
            if UserId <= 0 or FriendCache[UserId] ~= nil or FriendPending[UserId] then
                return
            end

            FriendPending[UserId] = true

            task.spawn(function()
                local IsFriend = false
                local Success, Result = Library.Call(
                    LocalPlayer.IsFriendsWith,
                    LocalPlayer,
                    UserId
                )

                if Success then
                    IsFriend = Result == true
                end

                FriendPending[UserId] = nil
                FriendCache[UserId] = IsFriend

                if Player.Parent == Players then
                    if RefreshRows then
                        task.defer(RefreshRows)
                    end
                    if State.Selected == Player and RefreshSelected then
                        RefreshSelected(false)
                    end
                end
            end)
        end

        local function IsCachedFriend(Player)
            if not Player or Player == LocalPlayer then
                return false
            end

            local UserId = tonumber(Player.UserId) or 0
            if FriendCache[UserId] == nil then
                QueueFriendCheck(Player)
                return false
            end

            return FriendCache[UserId] == true
        end

        local function GetPlayerPresentation(Player)
            local Status = GetStatus(Player)

            if Status == "Client" then
                return {
                    Status = Status,
                    Label = "Client",
                    Rank = 0,
                    Style = GetStatusStyle("Client"),
                    Highlight = true
                }
            end

            if Status == "Whitelist" then
                return {
                    Status = Status,
                    Label = "Whitelist",
                    Rank = 1,
                    Style = GetStatusStyle("Whitelist"),
                    Highlight = true
                }
            end

            if Status == "Priority" then
                return {
                    Status = Status,
                    Label = "Priority",
                    Rank = 2,
                    Style = GetStatusStyle("Priority"),
                    Highlight = true
                }
            end

            if Status == "Enemy" then
                return {
                    Status = Status,
                    Label = "Enemy",
                    Rank = 3,
                    Style = GetStatusStyle("Enemy"),
                    Highlight = true
                }
            end

            if IsCachedFriend(Player) then
                return {
                    Status = "None",
                    Label = "Friend",
                    Rank = 4,
                    Style = GetStatusStyle("Friend"),
                    Highlight = true
                }
            end

            return {
                Status = "None",
                Label = "None",
                Rank = 5,
                Style = GetStatusStyle("None"),
                Highlight = false
            }
        end

        local function SetStatus(Player, Status, Silent)
            if not Player or Player == LocalPlayer then
                return "Client"
            end

            Status = NormalizeStatus(Status)
            Menu.PlayerStatuses[
                tonumber(Player.UserId) or 0
            ] = Status

            if not Silent and type(State.StatusChanged) == "function" then
                task.spawn(State.StatusChanged, Player, Status)
            end

            if RefreshRows then RefreshRows() end
            if RefreshSelected then RefreshSelected(false) end
            return Status
        end

