        local ThumbnailCache = {}
        local LocalThumbnail = nil

        if LocalPlayer then
            local UserId =
                tonumber(LocalPlayer.UserId)
                or 0

            local Direct =
                "rbxthumb://type=AvatarHeadShot&id="
                .. tostring(UserId)
                .. "&w=150&h=150"

            ThumbnailCache[UserId] = Direct

            task.spawn(function()
                local Success, Content =
                    Library.Call(
                        Players.GetUserThumbnailAsync,
                        Players,
                        UserId,
                        Enum.ThumbnailType.HeadShot,
                        Enum.ThumbnailSize.Size150x150
                    )

                if Success
                    and type(Content) == "string"
                    and Content ~= ""
                then
                    LocalThumbnail = Content
                    ThumbnailCache[UserId] = Content

                    if State.Selected == LocalPlayer then
                        Avatar.Image = Content
                        AvatarLoading.Visible = false
                    end
                end
            end)
        end

        local function LoadAvatar(Player)
            State.ThumbnailSerial += 1
            local Serial = State.ThumbnailSerial

            Avatar.Image = ""
            AvatarLoading.Visible = true

            if not Player then
                return
            end

            local UserId =
                tonumber(Player.UserId)
                or 0

            local Cached =
                ThumbnailCache[UserId]

            if Player == LocalPlayer then
                local SettingsAvatar =
                    Menu.SettingsUI
                    and Menu.SettingsUI.ProfileAvatar

                local SettingsImage =
                    SettingsAvatar
                    and SettingsAvatar.Image

                if type(SettingsImage) == "string"
                    and SettingsImage ~= ""
                then
                    Cached = SettingsImage
                    ThumbnailCache[UserId] = SettingsImage
                elseif type(LocalThumbnail) == "string"
                    and LocalThumbnail ~= ""
                then
                    Cached = LocalThumbnail
                end
            end

            if type(Cached) == "string"
                and Cached ~= ""
            then
                Avatar.Image = Cached
                AvatarLoading.Visible = false
                return
            end

            local Direct =
                "rbxthumb://type=AvatarHeadShot&id="
                .. tostring(UserId)
                .. "&w=150&h=150"

            Avatar.Image = Direct
            AvatarLoading.Visible = false

            task.spawn(function()
                local Success, Content =
                    Library.Call(
                        Players.GetUserThumbnailAsync,
                        Players,
                        UserId,
                        Enum.ThumbnailType.HeadShot,
                        Enum.ThumbnailSize.Size150x150
                    )

                if Success
                    and type(Content) == "string"
                    and Content ~= ""
                then
                    ThumbnailCache[UserId] =
                        Content

                    if Serial == State.ThumbnailSerial
                        and State.Selected == Player
                    then
                        Avatar.Image = Content
                        AvatarLoading.Visible = false
                    end
                end
            end)
        end

        RefreshSelected = function(LoadImage)
            local Player = State.Selected
            local HasPlayer =
                Player ~= nil
                and Player.Parent == Players

            EmptyLabel.Visible = not HasPlayer
            Profile.Visible = HasPlayer
            CloseStatusDropdown()

            if not HasPlayer then
                PlayerName.Text = ""
                PlayerInfo.Text = ""
                Avatar.Image = ""
                AvatarLoading.Visible = false
                return
            end

            local Presentation = GetPlayerPresentation(Player)

            PlayerName.Text =
                tostring(Player.DisplayName or Player.Name)
            PlayerName.TextColor3 = Presentation.Highlight
                and Presentation.Style.Text
                or PrimaryText

            if Player.DisplayName ~= Player.Name then
                PlayerInfo.Text =
                    "@"
                    .. tostring(Player.Name)
                    .. "  ·  "
                    .. tostring(Player.UserId)
            else
                PlayerInfo.Text =
                    tostring(Player.UserId)
            end

            UpdateStatusVisual(Presentation.Label)

            StatusButton.Active =
                Player ~= LocalPlayer

            StatusButton.AutoButtonColor = false

            if LoadImage ~= false then
                LoadAvatar(Player)
            end
        end

