        RefreshRows = function()
            if State.Refreshing then
                State.RefreshQueued = true
                return
            end

            State.Refreshing = true
            State.RefreshGeneration += 1
            local Generation = State.RefreshGeneration

            for _, Child in ipairs(Scroll:GetChildren()) do
                if Child ~= RowLayout and Child:IsA("GuiObject") then
                    Child:Destroy()
                end
            end
            table.clear(State.Rows)

            local Query =
                string.lower(
                    tostring(State.Search or "")
                )

            local List = Players:GetPlayers()

            for _, Player in ipairs(List) do
                QueueFriendCheck(Player)
            end

            table.sort(List, function(A, B)
                local APresentation = GetPlayerPresentation(A)
                local BPresentation = GetPlayerPresentation(B)

                if APresentation.Rank ~= BPresentation.Rank then
                    return APresentation.Rank < BPresentation.Rank
                end

                local ADisplay = string.lower(tostring(A.DisplayName or A.Name))
                local BDisplay = string.lower(tostring(B.DisplayName or B.Name))
                if ADisplay ~= BDisplay then
                    return ADisplay < BDisplay
                end

                return string.lower(A.Name) < string.lower(B.Name)
            end)

            CountLabel.Text =
                "Players ["
                .. tostring(#List)
                .. "]"

            local Index = 0
            local SeenUserIds = {}

            for _, Player in ipairs(List) do
                local UserId = tonumber(Player.UserId) or 0
                local Haystack =
                    string.lower(
                        tostring(Player.Name)
                        .. " "
                        .. tostring(Player.DisplayName)
                    )

                if UserId > 0
                    and not SeenUserIds[UserId]
                    and (Query == ""
                        or string.find(
                            Haystack,
                            Query,
                            1,
                            true
                        ))
                then
                    SeenUserIds[UserId] = true
                    Index += 1
                    CreateRow(Player, Index)
                end
            end

            if Generation == State.RefreshGeneration then
                State.Refreshing = false
            end

            if State.RefreshQueued then
                State.RefreshQueued = false
                task.defer(RefreshRows)
            end
        end

        Bind(StatusButton.MouseButton1Click:Connect(function()
