        local Label =
            Create("TextLabel", {
                Parent = Root,
                Position =
                    UDim2.fromOffset(
                        29,
                        3
                    ),
                Size =
                    UDim2.new(
                        1,
                        -36,
                        1,
                        -6
                    ),
                BackgroundTransparency = 1,
                Font = Font,
                Text = FullText,
                TextColor3 =
                    Color3.fromRGB(
                        205,
                        213,
                        216
                    ),
