        Tween(
            IconHolder,
            0.11,
            {
                BackgroundTransparency = 0.88
            }
        )

        Tween(
            AccentRail,
            0.11,
            {
                BackgroundTransparency = 0.08
            }
        )

        GlobalState.Last[
            DedupeKey
        ] = {
            Root = Root,
            Time = CurrentTime
        }

        task.delay(
            Duration,
            function()
                if not Root
                    or not Root.Parent
                then
                    return
                end

                Tween(
                    Root,
